function travelReference(g,check=travelCheck(g)){return Number.isFinite(check.minimum)?`Percurso de referência: (${g.stops} paradas − 1) × 2,80 m = ${f(check.minimum)} m. Premissa de projeto informada pelo usuário; confira as distâncias reais entre pavimentos.`:'Informe as paradas para conferir a referência de 2,80 m por intervalo entre pavimentos.';}
