function modelCompareTable(scenarios){const rows=scenarioResults(scenarios),lines=[['Modelo',x=>MODEL_LABELS[x.study.trafficModel||'nbr5665']],['População adotada',x=>f(x.result.population.calculated??x.study.population,0)],['Elevadores',x=>f(selectedMetrics(x.result).count,0)],['Demanda / 5 min',x=>f(x.result.required)],['Capacidade do modelo / 5 min',x=>f(selectedMetrics(x.result).capacity)],['Intervalo do modelo (s)',x=>f(selectedMetrics(x.result).interval)],['Capacidade FAB / NBR apenas',x=>x.result.model==='iso8100'?'—':f(x.result.manufacturer.capacity)],['Mínimo estimado',x=>f((x.result.minimum.iso||x.result.minimum.normative).count,0)],['Partidas necessárias / h',x=>f(x.result.starts.totalRequired)],['Máximo de partidas / h',x=>f(x.result.starts.totalMaximum)]];return `<div class="table-wrap"><table><thead><tr><th>Indicador</th>${rows.map(x=>`<th>${esc(x.study.name)}</th>`).join('')}</tr></thead><tbody>${lines.map(([label,get])=>`<tr><td>${label}</td>${rows.map(x=>`<td>${esc(get(x))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function modelScenariosPage(){return head('Comparar cenários e modelos','Cada coluna mantém seu próprio motor, população e critérios.',button('navigate-study','Voltar ao estudo','','arrow')+button('save-scenario','Salvar cenário atual','','save',dirty?'disabled':''))+`<div class="scenario-grid">${scenarioResults(state.scenarios).map(x=>`<article class="card card-body"><div class="eyebrow">${esc(MODEL_LABELS[x.study.trafficModel||'nbr5665'])}</div><h3>${esc(x.study.name)}</h3><p>${f(selectedMetrics(x.result).count,0)} elevadores · capacidade ${f(selectedMetrics(x.result).capacity)} pessoas / 5 min</p><div class="buttons">${button('load-scenario','Abrir','small','arrow',`data-id="${esc(x.id)}"`)}${button('duplicate-scenario','Criar alternativa','small','copy',`data-id="${esc(x.id)}"`)}${button('delete-scenario','Excluir','small danger','trash',`data-id="${esc(x.id)}"`)}</div></article>`).join('')}</div><section class="card below"><div class="card-head"><h2>Comparação dos resultados</h2>${button('export-comparison','Exportar CSV','small','download')}</div>${modelCompareTable(state.scenarios)}<p class="card-body small-copy">Compare também população e critérios de cada modelo. Uma diferença de capacidade entre modelos não prova equivalência normativa. Nenhum resultado mistura fórmulas dos dois motores.</p></section>`;}
function exportModelComparison(){const rows=[['Cenário','Modelo','População','Elevadores','Demanda 5 min','Capacidade modelo 5 min','Intervalo modelo s','Mínimo estimado','Partidas necessárias h total','Máximo partidas h total']];for(const x of scenarioResults(state.scenarios)){const a=selectedMetrics(x.result);rows.push([x.study.name,x.study.trafficModel||'nbr5665',x.result.population.calculated??x.study.population,a.count,x.result.required,a.capacity,a.interval,(x.result.minimum.iso||x.result.minimum.normative).count,x.result.starts.totalRequired,x.result.starts.totalMaximum]);}download('Comparacao_de_cenarios.csv','\uFEFF'+rows.map(row=>row.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Comparação por modelo exportada.');}
function travelPreview(){
 const index=state.draft.groups[state.group]?state.group:0,g=state.draft.groups[index];let content;
 try{
  content=isReadOnly()?travelGroupPanels(result?.groups[index]?.travelCurves,g.label,{prefix:'preview',index}):calculateTravelPreview(state.draft,index).map(({group,curves,error},i)=>error?`<p class="population-warning"><strong>${esc(group.label)}:</strong> ${esc(error)}</p>`:travelGroupPanels(curves,group.label,{preview:true,prefix:'preview',index:`${index}-${i}`})).join('');
 }catch(error){content=`<p class="population-warning">${esc(error.message)}</p>`;}
 return `<div id="travel-preview"><details class="details-box travel-preview" open><summary>Curvas e tempos deste grupo · prévia</summary>${content}</details></div>`;
}
function groupApplication(i){const g=state.draft.groups[i];return `<div class="field"><label for="group-use-${i}">Aplicação do edifício · ${esc(g.label)}</label><select id="group-use-${i}" data-path="groups.${i}.use">${Object.entries(USES).filter(([k])=>k!=='auditorium').map(([k,v])=>`<option value="${k}" ${(g.use||state.draft.use)===k?'selected':''}>${esc(v.label)}</option>`).join('')}</select><small>Demanda e intervalo são avaliados pelo uso deste grupo. Confira os componentes de população dos pavimentos atendidos.</small></div>`;}
function isoHelpers(){return {field,select,checkField,button,speedField,motionField,travelPreview,timingWarnings,groupApplication};}
function modelSelector(){return `<section class="card card-body model-selection"><h2>Modelo de cálculo escolhido pelo cliente</h2>${select('Método do estudo','trafficModel',MODEL_LABELS,'Cada opção guarda seus parâmetros próprios. Ao trocar, os resultados anteriores são retirados e o cálculo completo precisa ser realizado novamente.')}</section>`;}
function isoStudyPage(){return studyPage();}

function isoAuxiliaryResults(print=false,charts=true){if(dirty||!result?.auxiliary?.length)return '';return `<section class="below"><h2>Estudos separados · modelo ISO</h2>${result.auxiliary.map((item,index)=>item.excluded?`<article class="card card-body"><h3>${esc(item.label)}</h3><p>${esc(item.basis)}</p></article>`:`<article class="card card-body below"><h3>${esc(item.label)}</h3><p>${f(item.population,0)} pessoas · demanda ${f(item.results.rate*100)}% · ${esc(item.basis)}</p>${isoInputMemory(item.study)}${isoResultsTable(item.results)}${isoMemory(item.results)}${isoStartsSection(item.results)}${charts?`${travelCurvesSection(item.study,item.results,{print,prefix:"aux-"+index})}${performanceSection(item.study,item.results,{print,prefix:"aux-"+index})}${energySection(item.study,item.results,{print,prefix:"aux-"+index})}`:""}${escalatorResults(item.results.population.escalators,item.study.populationCalc.rows)}<p>${esc(minimumMessage(item.study,item.results.minimum))}</p><ul>${item.results.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></article>`).join('')}</section>`;}
function isoAssumptionsPage(reference=false){return head(reference?'Verificação de conteúdo · ISO':'Premissas e memória · ISO','Conteúdo separado do modelo NBR 5665.',button('navigate-study','Voltar ao estudo','','arrow'))+`<section class="card card-body">${isoMethodology()}<h3>Capacidade das escadas · tabela enviada</h3><p>${esc(ESCALATOR_TABLE_SOURCE)}</p>${referenceTable(['Degrau (mm)','0,50 m/s (p/h)','0,65 m/s (p/h)','0,75 m/s (p/h)'],ESCALATOR_TABLE)}<p>Itens do documento: 4.3 (população), 5.1 / tabela 3 (critérios), 6.4 / tabela 7 (FC), 7 / fórmulas 4–19 (RTT), 9 / Anexo D (relatório). Adquira as normas oficiais na ABNT; o PDF anexado não é distribuído.</p></section><section class="card card-body below"><h2>Memória populacional do modelo</h2>${populationMemory()}</section>${!dirty&&result?.model==='iso8100'?`<section class="card below"><div class="card-head"><h2>Memória do RTT</h2></div>${isoMemory(result)}<div class="card-body">${isoInputMemory(state.draft)}<ul>${result.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div></section>`:''}`;}
function renderIsoPrint(){const s=result.calculationStudy||state.draft,r=result;const body=`<div class="report-head"><h1>Estudo de tráfego · modelo ISO 8100</h1><p>${esc(s.date)} · Motor ${esc(r.engineVersion)}</p></div>${firstPageIdentification(s)}${floorTableReport(s,esc,f)}${dimensionsReport(s,esc,f,r.dimensionReferences)}${transportReport(s,esc,f)}${fleetMassMemory(s,{esc,f})}${carTimingMemory(s,{esc,f})}${zonesSection(r,true)}<p>CNPJ do empreendimento / proprietário: ${esc(s.isoConfig.projectCnpj||'Não informado')} · aprovação do projeto: ${esc(s.isoConfig.approvalDate||'Não informada')}.</p><p class="population-warning">${esc(r.provenance||ISO_PROVENANCE)}</p>${sharedReadOnly&&r.engineVersion!==ENGINE_VERSION?'<p>Versão histórica: resultados preservados no motor original.</p>':''}<h2>População, composição e premissas</h2>${populationMemory()}<p>Como a população foi definida: ${esc(s.populationDefinition||'Não informado')}.</p><h2>Dados do equipamento</h2>${isoInputMemory(s)}<h2>Resultados e memória</h2>${isoResultsTable(r)}${isoMemory(r)}<p>${r.zoneSeparated?'Soma informativa das zonas: ':''}Capacidade ${f(r.iso.capacity)} pessoas / 5 min; demanda ${f(r.required)}; intervalo ${r.zoneSeparated?'avaliado por zona':f(r.iso.interval)+' s'}; limite ${r.zoneSeparated?'ver zona':r.limit===null?'N/A':f(r.limit)+' s'}.</p><p class="minimum-alert">${esc(minimumMessage(s,r.minimum))}</p>${isoStartsSection(r)}${r.groupSeparated?(s.operation.profile==='measured'?performanceSection(s,r,{print:true}):''):r.zoneSeparated?'':travelCurvesSection(s,r,{print:true})+performanceSection(s,r,{print:true})+(r.procurement?.offers?.length?'':energySection(s,r,{print:true}))}<h2>Premissas utilizadas</h2>${isoMethodology()}<ul>${r.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>${escalatorResults(r.population.escalators)}${isoAuxiliaryResults(true)}<h2>Referências e autoria</h2><p>Documento de trabalho N69 fornecido pelo proprietário, identificado como base da opção ISO8100. Tabela de capacidade teórica de escadas enviada em imagem; não atribuída à NBR 16734. Responsável: ${esc(s.annex.engineer)}. ${esc(s.annex.notes)}</p>`;const annex=(r.groupSeparated?r.groupStudies.map(c=>isoAnnex(c.study,c.results,c.label)).join(''):r.zoneSeparated?r.zones.map(z=>isoAnnex(z.study,z.results,z.label)).join(''):isoAnnex(s,r))+(r.auxiliary||[]).filter(item=>!item.excluded).map(item=>isoAnnex(item.study,item.results,item.label)).join('');$('#print-report').innerHTML=frameReport(body+procurementSummary(r.procurement||portal.procurement,{print:true})+annex,portal.reportProfile||portal.profile);}
function metrics(){if(isIso(state.draft))return isoMetrics(state.draft,dirty?null:result);const r=dirty?null:result,s=state.draft;if(r?.groupSeparated)return `<section class="card card-body"><h2>Estudos independentes por grupo</h2><p>${r.groupStudies.length} grupos · ${f(s.groups.reduce((n,g)=>n+(Number(g.count)||0),0),0)}<small>unidades</small>. Consulte população, demanda e atendimento de cada grupo abaixo. Totais de capacidade são apenas informativos.</p></section>`;return `<section class="metrics" aria-label="Resumo do estudo"><div class="metric"><div class="metric-label">Demanda em 5 minutos definida por norma${icon('users')}</div><div class="metric-value">${r?f(r.required):'—'}<small>pessoas</small></div><div class="metric-note">População adotada conforme norma de ${f(trafficRate(s)*100,0)}% sobre a população calculada/declarada de ${f(s.population,0)} pessoas</div></div><div class="metric highlight"><div class="metric-label">${s.use==='auditorium'?'Capacidade · ciclo NBR + premissas':s.groups.some(g=>g.speed>0&&g.speed<.63)?'Capacidade · NBR + premissa':'Capacidade · NBR 5665'}${icon('elevator')}</div><div class="metric-value">${r?f(r.normative.capacity):'—'}<small>pessoas / 5 min</small></div><div class="metric-note">${r?(s.commonService?(r.normative.capacityPass?'Capacidade suficiente':'Capacidade insuficiente'):'Soma informativa · zonas separadas'):'Recalcule após editar os parâmetros'}</div></div><div class="metric"><div class="metric-label">Intervalo consolidado${icon('clock')}</div><div class="metric-value">${r?f(r.normative.interval):'—'}<small>segundos</small></div><div class="metric-note">${r?(r.zoneSeparated?'Consulte o intervalo de cada zona':r.limit===null?'Apartamentos: critério não exigido':`Referência máxima: ${f(r.limit,0)} s`):'Resultados aguardam recálculo'}</div></div><div class="metric"><div class="metric-label">Elevadores no estudo${icon('compare')}</div><div class="metric-value">${f(s.groups.reduce((sum,g)=>sum+(Number(g.count)||0),0),0)}<small>unidades</small></div><div class="metric-note">${s.groups.length} conjunto${s.groups.length>1?'s':''} de características · até 20 grupos</div></div></section>`;}
function populationNotice(){if(dirty&&!currentPopulation())return '<p class="population-warning">Complete ou corrija os dados populacionais para atualizar o total. Os resultados anteriores foram retirados; o relatório exige cálculo completo.</p>';const status=sharedReadOnly&&result?.population?result.population:populationStatus(state.draft),warnings=sharedReadOnly?[]:populationWarnings(state.draft);return `${status.calculated!==null?`<p><strong>Última população calculada: ${f(status.calculated,0)} pessoas.</strong> População adotada no estudo: ${f(state.draft.population)} pessoas.</p>`:'<p>Calcule a população para registrar a composição e comparar com o total adotado.</p>'}${warnings.map(w=>`<p class="population-warning" role="status">${esc(w)}</p>`).join('')}`;}
function populationMemory(){const status=sharedReadOnly&&result?.population?result.population:populationStatus(state.draft);if(status.calculated===null)return `<p>População informada diretamente: ${f(state.draft.population)} pessoas. Como a população foi definida: ${esc(state.draft.populationBasis||'Não informado')}.</p>`;return `${populationSummary(status)}<p>População calculada: ${f(status.calculated,0)}. População adotada: ${f(state.draft.population)}. ${isIso(state.draft)?'Total após arredondamento por pavimento':'Total antes do arredondamento final para cima'}: ${f(status.raw,4)}.</p><div class="table-wrap"><table><thead><tr><th>Andar servido</th><th>Composição / posição / ambiente</th><th>Memória</th><th>Bruta</th><th>Desconto</th><th>Líquida</th></tr></thead><tbody>${[...status.lines].reverse().map(row=>`<tr><td>${esc(row.servedFloorMark??row.floorMark)}${row.streetAccessExcluded?' · acesso':''}</td><td>${esc(row.compositionName||compositionName(row))} · ${esc(row.floorMark)} · ${esc(row.label)}</td><td>${esc(row.formula)}<br><small>${esc(row.details)}</small></td><td>${f(row.gross,4)}</td><td>${f(row.discount*100,0)}%</td><td>${f(row.net,4)}</td></tr>`).join('')}</tbody></table></div>${(sharedReadOnly?[]:populationWarnings(state.draft)).map(w=>`<p class="population-warning">${esc(w)}</p>`).join('')}${escalatorResults(status.escalators,state.draft.populationCalc.last?.rows)}`;}
function checkField(label,path,help='',attrs=''){
 const value=path.split('.').reduce((x,k)=>x?.[k],state.draft);
 return `<label class="check"><input type="checkbox" data-path="${path}" ${value?'checked':''} ${attrs}><span>${label}${help?`<small>${help}</small>`:''}</span></label>`;
}
function currentPopulation(){if(sharedReadOnly&&result?.population)return result.population;try{return calculatePopulation(state.draft.use,state.draft.populationCalc.rows,populationOptions(state.draft));}catch{return null;}}
function environmentCalculation(row,i,preview=currentPopulation()){try{let data=preview;if(!data){const effective={...row,isStreetAccess:state.draft.populationCalc.rows.some(x=>x.isStreetAccess)&&row.floor===state.draft.populationCalc.accessFloor};data=calculatePopulation(state.draft.use,[effective],{...populationOptions(state.draft),additionalLines:[],escalators:{enabled:false}});i=0;}return f(data.declarationSummary[i].calculated,4);}catch{return '—';}}
function populationExclusionNotice(row,i,preview){let line=preview?.lines[i];if(!line){try{line=calculatePopulation(state.draft.use,[{...row,isStreetAccess:state.draft.populationCalc.rows.some(r=>r.isStreetAccess)&&row.floor===state.draft.populationCalc.accessFloor}],{...populationOptions(state.draft),additionalLines:[],escalators:{enabled:false}}).lines[0];}catch{}}return line?.exclusionNotice?`<p class="population-warning">${esc(line.exclusionNotice)}</p>`:'';}
function autoPopulation(){if(isBasic(state.draft))return;try{const pc=calculatePopulation(state.draft.use,state.draft.populationCalc.rows,populationOptions(state.draft));state.draft.population=pc.value;state.draft.populationBasis=pc.basis+(state.draft.populationDefinition?.trim()?'\nComo a população foi definida: '+state.draft.populationDefinition.trim():'');state.draft.populationCalc.last=populationSnapshot(state.draft);return pc;}catch{return null;}}
function schoolWarning(row){return row.schoolDiscountPercent>0&&row.schoolDiscountPercent!==30?`O desconto escolar de ${f(row.schoolDiscountPercent)}% será aplicado como premissa personalizada. ${isIso(state.draft)?'O documento informado, 4.3.3.2':'A NBR 5665, 5.1.3'}, indica 30%.`:'';}
function populationSummary(data,preview=false){
 if(!data)return '<p class="small-copy">Preencha os componentes para conferir a população de todos os estudos.</p>';
 return `<div class="population-summary"><h3>${preview?'Prévia por andar servido':'Resumo por andar servido'}</h3><div class="summary-strip"><div><span>Estudo principal</span><strong>${f(data.value,0)} pessoas</strong></div><div><span>Estudos separados</span><strong>${f(data.separateValue||0,0)} pessoas</strong></div><div><span>Total dos estudos</span><strong>${f(data.totalValue??data.value,0)} pessoas</strong></div></div><div class="table-wrap"><table><thead><tr><th>Andar servido</th><th>Ambientes somados</th><th>Calculada (antes das exclusões)</th><th>Declarada dos ambientes</th><th>Não computada</th><th>Destinada aos elevadores</th><th>Principal / separados</th></tr></thead><tbody>${[...(data.floors||[])].reverse().map(floor=>`<tr><td>${esc(floor.marks.join(' / '))}${floor.streetAccess?' · acesso':''}<small>Nível ${floor.floor}</small></td><td>${floor.environments.map(esc).join(', ')}</td><td>${f(floor.calculated,4)}</td><td>${f(floor.declared,0)}</td><td>${f(floor.notComputed??0,4)}<small>Escadas: ${f(floor.escalatorServed??0,4)}</small></td><td>${f(floor.adopted,4)}${(floor.notices||[]).map(n=>`<small class="population-warning">${esc(n)}</small>`).join('')}</td><td>${f(floor.main,4)} / ${f(floor.separate,4)}</td></tr>`).join('')}</tbody></table></div><p class="small-copy">Em cada ambiente, adota-se o maior valor entre a população calculada e a declarada. Cada andar e estudo soma uma única vez os valores adotados de seus ambientes. Valores declarados iguais em ambientes distintos são somados; calculada e declarada do mesmo ambiente não são somadas entre si. Estudos separados preservam seus próprios critérios. A população calculada permanece registrada mesmo quando excluída. A coluna não computada compara o total registrado (maior entre calculado e declarado por ambiente) com o destinado aos elevadores. Escadas com atendimento parcial deixam nos elevadores a diferença em pessoas. ${preview?'O botão Calcular estudo completo aplica a população e atualiza todos os resultados.':''}</p></div>`;
}
function populationForm(){
 const pc=state.draft.populationCalc,preview=currentPopulation(),use=state.draft.use,accessIndex=pc.rows.findIndex(row=>row.isStreetAccess),access=pc.rows[accessIndex];
 return `<section class="population-calculator" aria-labelledby="population-title"><div class="section-heading"><div><h2 id="population-title">Cálculo populacional</h2><p>Inclua os pavimentos e ambientes na composição. Identifique o ambiente e o andar que ele atende. Vários ambientes podem servir o mesmo andar; o resumo soma essas parcelas. A posição identifica apenas a ordem da composição no estudo.</p></div>${button('add-population-row','Adicionar composição','small','plus',pc.rows.length>=100?'disabled':'')}</div>
 <div class="fields"><div class="field"><label>Pavimento principal de acesso à rua</label><div class="field-note">${access?`<strong>${esc(access.servedFloorMark)} · ${esc(access.label)}</strong><br>Nível de cálculo: 0. Sua população é desconsiderada.`:'Nenhuma composição confirmada como acesso à rua. Marque o flag na composição correspondente. O estudo usa o nível '+pc.accessFloor+' como referência enquanto não houver confirmação.'}</div></div></div>
 ${state.draft.entryVersion===8?populationFloorTabs():''}${pc.rows.map((row,i)=>({row,i})).filter(({row})=>state.draft.entryVersion!==8||row.servedFloorMark===populationFloorSelection()).reverse().map(({row,i})=>{
 const use=applicationForRow(state.draft,row),type=POP_TYPES[row.kind],path=`populationCalc.rows.${i}.`,extra=['garage','restaurant','auditorium'].includes(row.kind),exclusive=row.mode==='exclusive',condition=!exclusive&&(row.kind==='garage'&&row.participation==='include'||use==='school'&&row.mode==='main'||row.discount!=='none'||row.exclusion!=='none'||row.reduction15);
 const destinations={...(defaultPopulationMode(use,row.kind,state.draft.trafficModel)==='main'?{main:'População do estudo principal'}:{}),...(row.kind!=='auditorium'?{exclusive:'Uso exclusivo da edificação · desconsiderar população'}:{}),external:row.kind==='auditorium'?'Auditório · estudo separado por assentos':'Atende outras demandas · estudo separado'};
 return `<details class="population-row composition-panel" name="population-compositions" ${(state.populationRow??0)===i?'open':''}><summary data-action="open-composition" data-index="${i}"><strong id="composition-name-${i}">${esc(compositionName(row))}</strong><span id="composition-population-${i}">${esc(row.label)} · calculada ${environmentCalculation(row,i,preview)} · elevadores ${preview?f(preview.lines[i].net,4):'—'} pessoas</span></summary><article><div class="section-heading"><strong>Composição ${i+1} · posição ${esc(row.floorMark)} · andar ${esc(row.servedFloorMark)}${row.mode==='external'?' · estudo separado':exclusive?' · uso exclusivo':''}</strong><div class="composition-actions">${button('copy-population-row','Copiar','small','copy',`data-index="${i}" ${pc.rows.length>=100?'disabled':''}`)}${button('move-population-row','Subir','small','',`data-index="${i}" data-direction="1" ${i===pc.rows.length-1?'disabled':''}`)}${button('move-population-row','Descer','small','',`data-index="${i}" data-direction="-1" ${i===0?'disabled':''}`)}${pc.rows.length>1?button('remove-population-row','Remover','small danger','trash',`data-index="${i}"`):''}</div></div><div class="fields">
 <div class="field"><label>Nome da composição</label><input id="composition-auto-name-${i}" readonly value="${esc(compositionName(row))}"><small>Nome automático pelo andar servido; a indicação do ambiente é preservada separadamente.</small></div>${field('Indicação do ambiente',path+'label' ,'text','','maxlength="120"')}${field('Posição da composição no estudo',path+'floorMark','text','Identifica a composição, com até 2 caracteres. Renumera apenas as posições posteriores; não altera os andares atendidos.','data-floor-mark maxlength="2" autocomplete="off"')}${state.draft.floorTable?.enabled?servedFloorSelect(row,i):field('Andar servido pela composição',path+'servedFloorMark','text','Informe a marcação real do andar. Pode repetir em vários ambientes; o resumo reúne todos no mesmo andar.','data-served-floor maxlength="2" autocomplete="off"')}${!state.draft.floorTable?.enabled&&/[A-Z]/.test(row.servedFloorMark)?field('Nível físico do andar',path+'servedFloorLevel','number','Para marcações com letras, informe o nível: 0 no acesso, positivos acima e negativos abaixo. Ambientes do mesmo andar compartilham este nível.','data-served-floor-level min="-200" max="200"'):''}${select('Componente de população',path+'kind',populationTypes(state.draft.groups.map(g=>g.use||state.draft.use),state.draft.trafficModel))}${row.participationVersion===1?select('Esta população participa do estudo?',path+'participation',{'':'Selecionar participação',include:'Sim · incluir no estudo principal',separate:'Estudo separado para esta demanda',exclude:'Não · registrar sem somar à população'},'A inclusão de componente complementar no estudo principal é uma premissa explícita do gestor.'):extra?select('Destinação da população',path+'mode',destinations,'Uso exclusivo de apoio é desconsiderado; demanda externa recebe um estudo separado.'):''}${field(isIso(state.draft)&&row.kind==='office'?'Área interna útil (m²)':type.unit,path+'amount','number',exclusive?'Quantidade ou área para registro, inclusive zero; não acrescenta população ao estudo.':isIso(state.draft)?'Regra da classe e do componente do documento ISO informado.':type.rule||`${f(type.factor||1/type.divisor)} pessoa(s) por ${type.area?'m²':'unidade'}.`,'min="0" max="1000000"')}${field('Repetições no mesmo pavimento',path+'repeat','number','Para outros pavimentos, adicione outra composição.','min="1" max="100000"')}
 ${isIso(state.draft)?isoPopulationFields(state.draft,row,i,isoHelpers()):''}
 ${!exclusive?select('Desconto de 50% da população',path+'discount',{none:'Não aplicar',adjacent50:'Aplicar desconto de 50%'},`Desconto de 50% da população, nos pavimentos imediatamente acima e ou abaixo do principal com até 5 m de percurso. ${use==='offices'?'Em escritórios, até dois pavimentos: um imediatamente acima e um imediatamente abaixo do acesso.':'Neste projeto, aplicar em somente um andar.'} Ambientes do mesmo andar podem compartilhar a condição.`):''}
 ${!exclusive&&row.discount==='adjacent50'?field('Percurso até o pavimento de acesso (m)',path+'distance','number',isIso(state.draft)?'Documento ISO informado, 4.3.3.1.':'Somente pavimento imediatamente acima ou abaixo. NBR 5665, 5.1.2.','min="0" max="5" '+(state.draft.floorTable?.enabled?'readonly':'')):''}
 ${use==='school'&&row.mode==='main'?field('Desconto escolar da população (%)',path+'schoolDiscountPercent','number',isIso(state.draft)?'Documento 4.3.3.2: 30%; outro valor exige premissa personalizada.':'0 = sem desconto. Referência da NBR 5665, 5.1.3: 30%. O percentual informado entra no cálculo e não se acumula com o desconto de 50%.','min="0" max="100"')+field('Percurso para o desconto escolar (m)',path+'schoolDistance','number',isIso(state.draft)?'Somente imediatamente acima ou abaixo, até 12 m.':'Pavimentos acima ou imediatamente abaixo do acesso, até 12 m.','min="0" max="12" '+(state.draft.floorTable?.enabled?'readonly':'')):''}
 ${!exclusive&&transportOptions(state.draft).escalators===true?select('População não computada no estudo quando atendida por escadas rolantes',path+'escalatorDiscount',{false:'Não solicitar',true:'Avaliar população atendida pelas escadas rolantes'},'Atendimento integral: população não computada nos elevadores. Atendimento parcial: somente a parcela atendida deixa de ser computada; a diferença permanece no estudo. Requer ligação contínua e conferência da capacidade.'):''}${!exclusive?select('Outras exclusões da população',path+'exclusion',{none:'Não excluir',exclusive:isIso(state.draft)?'Apoio exclusivo acima do acesso · 4.3.3.5':'Área de apoio de uso exclusivo · 5.1.7',...(row.kind==='office'?{unusable:'Área sem possibilidade de uso para trabalho · 5.1.4'}:{})},'Para garagens e restaurantes de apoio, selecione Uso exclusivo em Destinação da população.'):''}${field('Observações e justificativas',path+'notes','textarea','Descreva as condições de descontos e exclusões; paradas e percurso são preservados.')}${row.kind==='auditorium'?auditoriumFields(path):''}</div>
 ${checkField('Este pavimento é o acesso à rua.',path+'isStreetAccess','Somente um pavimento pode ser confirmado. Com a tabela ativa, o acesso é definido pelo andar principal selecionado, independentemente da marcação. Sua população é registrada na memória, mas não entra na demanda de elevadores.',state.draft.floorTable?.enabled||accessIndex>=0&&accessIndex!==i?'disabled':'')}
 ${row.isStreetAccess?'<p class="population-warning">Acesso à rua confirmado: população deste pavimento desconsiderada no estudo. Paradas e percurso permanecem considerados.</p>':''}
 ${row.kind==='office'&&!isIso(state.draft)?checkField('Desconto populacional de 15%',path+'reduction15','Somente sala ≥ 200 m² ou sala corrida de pavimento inteiro · NBR 5665, 5.1.5.'):''}
 ${!exclusive&&transportOptions(state.draft).escalators===true&&(row.discount!=='none'||row.schoolDiscountPercent>0||row.reduction15||row.exclusion!=='none'||row.escalatorDiscount||row.servedByEscalator)?checkField(row.mode==='external'?'Esta demanda usa a mesma rede de escadas rolantes desde o acesso.':'Pavimento servido por escadas rolantes desde o acesso',path+'servedByEscalator','Solicita a exclusão e inclui esta população na capacidade acumulada da rede. A exclusão depende da continuidade, do par de subida/descida e da capacidade.'):''}
 ${row.servedByEscalator&&transportOptions(state.draft).escalators===true?button('configure-floor-escalators','Configurar escadas deste pavimento','small','',`data-index="${i}"`):''}${condition?checkField(row.kind==='garage'&&(row.mode==='external'||row.participation==='include')?'Confirmo os descontos e a garagem com rampas, sem manobrista.':'Confirmo as condições do desconto, redução ou exclusão.',path+'conditionsConfirmed','Confirme as condições dos itens normativos correspondentes.'):''}
 ${row.mode==='external'&&row.kind==='garage'&&!condition?checkField('Confirmo garagem com rampas, sem manobrista.',path+'conditionsConfirmed','Necessário para aplicar 1,4 pessoa por vaga · NBR 5665, 5.1.1 h.'):''}
 ${exclusive?'<p class="population-warning">Uso exclusivo da edificação: população desconsiderada do estudo, conforme NBR 5665, 5.1.7. Preserve as paradas e o percurso.</p>':''}
 <div class="fields environment-population"><div class="field"><label for="population-calculated-${i}">População calculada do ambiente (pessoas)</label><input id="population-calculated-${i}" type="text" readonly value="${environmentCalculation(row,i,preview)}"><small>Calculada pelos dados do ambiente, após descontos percentuais e antes das exclusões de participação, uso/acesso e atendimento por escadas. Continua visível mesmo quando não entra no estudo.</small></div>${field('População declarada do ambiente (pessoas)',path+'declaredPopulation','number','0 = sem declaração. Total deste ambiente, incluindo as repetições da composição. Adota-se o maior valor entre calculada e declarada, contando o ambiente uma única vez.','min="0" max="1000000"')}<div class="field wide"><label>População adotada nos elevadores</label><output id="population-adopted-${i}">${preview?f(preview.lines[i].net,4)+' pessoas':'Aguardando dados válidos de todo o estudo'}</output></div></div>
 <div id="population-row-notice-${i}" class="population-row-notice" aria-live="polite">${populationExclusionNotice(row,i,preview)}${floorMarkWarning(row,pc.accessFloor,state.draft.floorTable?.enabled?accessRow(state.draft.floorTable)?.mark:'0')?`<p class="population-warning">${esc(floorMarkWarning(row,pc.accessFloor,state.draft.floorTable?.enabled?accessRow(state.draft.floorTable)?.mark:'0'))}</p>`:''}${schoolWarning(row)?`<p class="population-warning">${esc(schoolWarning(row))}</p>`:''}${row.servedByEscalator&&!exclusive?`<p class="population-warning">${esc(preview?.lines[i]?.details||'Preencha a composição e configure as escadas rolantes para verificar esta exclusão.')}</p>`:''}</div>
</article></details>`;
 }).join('')}
 <div id="population-summary" aria-live="polite">${populationSummary(preview,true)}</div>
 <div class="fields population-total">${field('População adotada no estudo principal (pessoas)','population','number','Resultado automático. Para declarar população, use o campo do ambiente na composição.','readonly min="0" max="1000000"')}${field('Como a população foi definida?','populationDefinition','textarea','Explique a origem das declarações e decisões de ocupação. O texto é preservado nos recálculos e incluído no relatório, junto da memória automática.')}</div><div class="population-status" id="population-notice" aria-live="polite">${populationNotice()}</div><div class="field-note">Qualquer botão de cálculo atualiza população, estudos e relatório juntos. As populações dos estudos separados não são somadas à demanda principal. Exclusões não removem paradas ou percurso.</div></section>`;
}
function auditoriumFields(prefix){return `${field('Demanda do auditório em 5 min (%)',prefix+'auditoriumDemandPercent','number','Premissa de projeto; o valor inicial de 100% modela todos os assentos em 5 min. Ajuste ao evento.','min="0.01" max="100"')}${field('Intervalo máximo de projeto (s)',prefix+'auditoriumInterval','number','Premissa editável, inicialmente 60 s. As normas fornecidas não fixam percentual ou intervalo específico para auditórios.','min="1" max="3600"')}`;}
function escalatorForm(preview){
 const config=state.draft.populationCalc.escalators,p='populationCalc.escalators.';if(config.graphVersion===2)return escalatorNetworkEditor(state.draft,{field,select,checkField,button,esc,f},preview);if(config.graphVersion===1)return graphEscalatorForm(preview);
 return `<section class="transport-section" aria-labelledby="escalator-title"><h3 id="escalator-title">Escadas rolantes e pavimentos atendidos</h3>${button('upgrade-escalators','Configurar trechos e quantidades por sentido','small','refresh')}<p class="small-copy">${esc(ESCALATOR_REFERENCE_HELP)}</p>${checkField('Controlar atendimento por escadas rolantes',p+'enabled',isIso(state.draft)?ESCALATOR_EXCLUSION_HELP.replace('NBR 5665, item 5.1.6','documento ISO informado, item 4.3.3.4'):ESCALATOR_EXCLUSION_HELP,hasSelectedEscalatorFloor(state.draft)?'':'disabled')}${config.enabled?`<div class="fields transport-fields">${field('Pavimentos acima do acesso',p+'aboveCount','number','','min="0" max="40"')}${field('Pavimentos abaixo do acesso',p+'belowCount','number','','min="0" max="40"')}${select('Base de capacidade das escadas',p+'capacityBasis',{'provided-table':'Tabela da imagem enviada',manufacturer:'Dados documentados do fabricante'})}${field('Janela de transporte (min)',p+'periodMinutes','number','Premissa de estudo; converte a capacidade horária adotada para a janela escolhida.','min="0.1" max="120"')}${field('População a transportar na janela (%)',p+'demandPercent','number','Inicialmente 100% da população acumulada dos pavimentos atendidos.','min="0.01" max="100"')}${field('Utilização da capacidade informada (%)',p+'utilizationPercent','number','Premissa operacional, inicialmente 100%. Confirme o valor aplicável com o fabricante.','min="0.01" max="100"')}</div><div class="buttons">${button('layout-escalators','Atualizar tabela de pavimentos','small','refresh')}</div><p class="small-copy">Cada linha liga o pavimento indicado ao nível anterior na direção do acesso. Selecione os trechos servidos e confirme uma escada para subir e outra para descer, com a mesma largura de degrau. Dimensões de 600, 800 ou 1.000 mm.</p>
 <div class="table-wrap escalator-inputs"><table><thead><tr><th>Trecho</th><th>Atende</th><th>Existência</th><th>Degrau subida</th><th>Degrau descida</th><th>v subida (m/s)</th><th>v descida (m/s)</th><th>Inclinação (°)</th><th>Desnível (m)</th><th>Capacidade subida (p/h)</th><th>Capacidade descida (p/h)</th></tr></thead><tbody>${config.links.map((link,i)=>({link,i})).sort((a,b)=>b.link.floor-a.link.floor).map(({link,i})=>{const lp=p+`links.${i}.`,from=link.from??link.floor+(link.floor>state.draft.populationCalc.accessFloor?-1:1);return `<tr><td>${floorCaption(from)} ↔ ${floorCaption(link.floor)}</td><td>${checkField('Servido',lp+'served')}</td><td>${checkField('Subida',lp+'upPresent')}${checkField('Descida',lp+'downPresent')}</td><td>${select('Largura (mm)',lp+'widthUp',{600:'600',800:'800',1000:'1000'})}</td><td>${select('Largura (mm)',lp+'widthDown',{600:'600',800:'800',1000:'1000'})}</td><td>${field('Velocidade',lp+'speedUp','number','','min="0.01" max="2"')}</td><td>${field('Velocidade',lp+'speedDown','number','','min="0.01" max="2"')}</td><td>${field('Inclinação',lp+'incline','number','','min="1" max="60"')}</td><td>${field('Desnível',lp+'rise','number','','min="0.1" max="100"')}</td><td>${config.capacityBasis==='provided-table'?`<strong id="esc-table-up-${i}">${f(tableEscalatorCapacity(link.widthUp,link.speedUp))}</strong><small>Capacidade teórica da tabela</small>`:field('Capacidade por hora',lp+'capacityUpHourly','number','0 = não informada','min="0" max="100000"')}</td><td>${config.capacityBasis==='provided-table'?`<strong id="esc-table-down-${i}">${f(tableEscalatorCapacity(link.widthDown,link.speedDown))}</strong><small>Capacidade teórica da tabela</small>`:field('Capacidade por hora',lp+'capacityDownHourly','number','0 = não informada','min="0" max="100000"')}</td></tr>`;}).join('')}</tbody></table></div>

 <div class="transport-results" id="escalator-results" aria-live="polite">${preview?escalatorResults(preview.escalators):'<p class="small-copy">Preencha as composições e os parâmetros válidos para obter o estudo por trecho.</p>'}</div>`:''}</section>`;
}
function floorCaption(level,rows=state.draft.populationCalc.rows){const row=rows?.find(row=>row.floor===level),mark=row?.servedFloorMark??row?.floorMark??String(level);return mark===String(level)?esc(mark):`${esc(mark)} (nível ${level})`;}
function escalatorResults(network,rows=state.draft.populationCalc.rows){
 if(!network?.enabled)return '';if(network.graphVersion===2)return escalatorNetworkReport(network,{esc,f,caption:floor=>floorCaption(floor,rows)});
 return `${escalatorAllocationReport(network,{esc,f,caption:floor=>floorCaption(floor,rows)})}${!['manufacturer','provided-table'].includes(network.capacityBasis)?'<p class="population-warning">Registro histórico de escadas: capacidade anterior não validada na base atual. O proprietário deve reabrir, informar os dados do fabricante e recalcular o projeto antes de emitir uma nova versão.</p>':''}<h3>Estudo de tráfego por trecho de escadas rolantes</h3><p class="small-copy">Janela ${f(network.periodMinutes)} min · demanda ${f(network.demandPercent)}% · utilização ${f(network.utilizationPercent)}%. Capacidade na janela = capacidade horária documentada do fabricante × minutos / 60 × utilização / 100. Base: ${network.capacityBasis==='provided-table'?'capacidade teórica da tabela enviada':'dados do fabricante'}. A tabela enviada é uma premissa do proprietário; não está sendo atribuída à NBR 16734. Subida e descida são avaliadas separadamente, sem somar suas capacidades.</p><div class="table-wrap"><table><thead><tr><th>Trecho</th><th>População acumulada</th><th>Demanda na janela</th><th>Capacidade adotada subida/descida (p/h)</th><th>Capacidade subida/descida na janela</th><th>Condição</th></tr></thead><tbody>${[...network.segments].sort((a,b)=>b.floor-a.floor).map(segment=>`<tr><td>${floorCaption(segment.from,rows)} ↔ ${floorCaption(segment.floor,rows)}<small>Pavimentos: ${segment.dependentFloors.map(floor=>floorCaption(floor,rows)).join(', ')}</small><small>Documento: ${esc(segment.capacitySource||'Não registrado nesta versão')}<br>Degraus: ${f(segment.widthUp,0)} / ${f(segment.widthDown,0)} mm · velocidades: ${f(segment.speedUp)} / ${f(segment.speedDown)} m/s<br>Inclinação: ${f(segment.incline)}° · desnível: ${f(segment.rise)} m · configuração técnica: ${segment.geometryConfirmed?'confirmada':'sem confirmação atual'}</small></td><td>${f(segment.population)}</td><td>${f(segment.demand)}</td><td>${f(segment.hourlyUp??segment.theoreticalUp)} / ${f(segment.hourlyDown??segment.theoreticalDown)}</td><td>${f(segment.capacityUp)} / ${f(segment.capacityDown)}</td><td class="text-cell">${segment.pass?'Capacidade atende nas premissas informadas':esc(segment.issues.join('; '))}</td></tr>`).join('')}</tbody></table></div><p><strong>População desconsiderada nos elevadores: ${f(network.excludedPopulation)} pessoas.</strong></p>${Object.entries(network.floors).map(([floor,condition])=>`<p class="small-copy"><strong>Pavimento ${floor}:</strong> ${esc(condition.reason)}</p>`).join('')}<p class="small-copy">A demanda de cada trecho inclui os pavimentos além dele com atendimento contínuo e os usos externos vinculados à mesma rede. Uma interrupção, par sem confirmação, larguras diferentes, configuração técnica sem conferência ou gargalo mantém a população dependente no estudo de elevadores. A exclusão também precisa do flag na composição. Preservar paradas e percurso.</p>`;
}
function auxiliarySpeedField(i,j,g){const p=`populationCalc.rows.${i}.groups.${j}.speed`,id='f-'+p.replaceAll('.','-'),preset=SPEED_OPTIONS.includes(g.speed)?String(g.speed):'custom';return `<div class="field"><label for="${id}">Velocidade nominal (m/s)</label><div class="speed-entry"><select id="aux-speed-${i}-${j}" data-aux-speed-preset="${p}" aria-label="Escolher velocidade na tabela"><option value="custom" ${preset==='custom'?'selected':''}>Outro valor</option>${SPEED_OPTIONS.map(v=>`<option value="${v}" ${preset===String(v)?'selected':''}>${f(v)} m/s</option>`).join('')}</select><input id="${id}" type="number" data-path="${p}" value="${g.speed}" step="any" min="0" required></div><small>Tabela ou qualquer outro valor positivo digitado.</small></div>`;}
function auxiliaryMotionField(i,j,g,key){const p=`populationCalc.rows.${i}.groups.${j}.${key}`,id='f-'+p.replaceAll('.','-'),check=motionCheck(g),a=key==='acceleration',color=a?(check.accelerationRed?'red':check.accelerationYellow?'yellow':''):(check.jerkYellow?'yellow':'');return `<div class="field"><label for="${id}">${a?'Aceleração (m/s²)':'Jerk (m/s³)'}</label><div class="motion-entry">${[-1,1].map((direction,index)=>`${index?`<input id="${id}" type="number" data-path="${p}" data-aux-motion-key="${key}" data-aux-index="${i}" data-aux-group="${j}" value="${g[key]}" step="0.05" min="0" class="${color?(a?'motion-warning-'+color:'jerk-warning-yellow'):''}" aria-describedby="${id}-alert">`:''}<button type="button" class="motion-step" data-action="auxiliary-motion-step" data-index="${i}" data-group="${j}" data-key="${key}" data-direction="${direction}" aria-label="${direction<0?'Diminuir':'Aumentar'} ${a?'aceleração':'jerk'} em 0,05">${direction<0?'−':'+'}</button>`).join('')}</div><small>${motionHelp(g,key)}</small><small id="${id}-alert" class="motion-alert ${color}" role="status" ${color?'':'hidden'}>${esc(a?accelerationMessage(g):jerkMessage(g))}</small></div>`;}
function auxiliaryTravelField(i,j,g){const p=`populationCalc.rows.${i}.groups.${j}.travel`,id='f-'+p.replaceAll('.','-'),check=travelCheck(g);return `<div class="field"><label for="${id}">Percurso (m)</label><input id="${id}" type="number" data-path="${p}" value="${g.travel}" step="any" min="0.1" max="1000" class="${check.below?'travel-warning':''}" aria-invalid="${check.below}" aria-describedby="${id}-alert"><small id="${id}-alert" class="travel-alert" role="status">${esc(check.below?travelMessage(g,check):travelReference(g,check))}</small></div>`;}
function changeAuxiliaryMotion(i,j,key,direction){const g=state.draft.populationCalc.rows[i]?.groups?.[j];if(!g||!['acceleration','jerk'].includes(key)||![-1,1].includes(direction))return;const value=round((Number.isFinite(g[key])?g[key]:0)+direction*.05,10);if(value<=0){toast('O valor precisa permanecer maior que zero.');return;}g[key]=value;const el=$(`#f-populationCalc-rows-${i}-groups-${j}-${key}`);if(el)el.value=String(value);markDirty();persist();updateDerived();}
function updateAuxiliaryControls(){for(const [i,item] of state.draft.populationCalc.rows.entries())for(const [j,g] of (item.groups||[]).entries()){
 const prefix=`f-populationCalc-rows-${i}-groups-${j}-`,check=motionCheck(g);
 for(const key of ['acceleration','jerk']){const input=$('#'+prefix+key),alert=$('#'+prefix+key+'-alert'),a=key==='acceleration',red=a&&check.accelerationRed,yellow=a?check.accelerationYellow:check.jerkYellow;if(input){input.classList.toggle('motion-warning-red',red);input.classList.toggle('motion-warning-yellow',a&&yellow);input.classList.toggle('jerk-warning-yellow',!a&&yellow);}if(alert){alert.hidden=!(red||yellow);alert.classList.toggle('red',red);alert.classList.toggle('yellow',yellow);alert.textContent=a?accelerationMessage(g):jerkMessage(g);}}
 const travel=$('#'+prefix+'travel'),alert=$('#'+prefix+'travel-alert'),t=travelCheck(g);if(travel){travel.classList.toggle('travel-warning',t.below);travel.setAttribute('aria-invalid',String(t.below));}if(alert)alert.textContent=t.below?travelMessage(g,t):travelReference(g,t);
 const speed=$(`#aux-speed-${i}-${j}`);if(speed)speed.value=SPEED_OPTIONS.includes(g.speed)?String(g.speed):'custom';
}}
function auxiliaryGroup(i,j){
 if(isIso(state.draft)){const item=state.draft.populationCalc.rows[i],p=`populationCalc.rows.${i}.groups.${j}.`;return `<article class="auxiliary-group"><h3>Grupo ${j+1} · ISO</h3>${item.groups.length>1?button('remove-auxiliary-group','Remover grupo','small danger','trash',`data-index="${i}" data-group="${j}"`):''}${isoGroupFields(state.draft,item.groups[j],p,isoHelpers(),{auxiliary:true})}</article>`;}
 const p=`populationCalc.rows.${i}.groups.${j}.`,groups=state.draft.populationCalc.rows[i].groups,g=groups[j];
 return `<article class="auxiliary-group"><div class="section-heading"><strong>Grupo ${j+1}</strong>${groups.length>1?button('remove-auxiliary-group','Remover grupo','small danger','trash',`data-index="${i}" data-group="${j}"`):''}</div><div class="fields">${[['Elevadores','count','min="1" max="30"'],['Lotação útil (pessoas)','capacity','min="1" max="100"'],['Paradas incluindo acesso','stops','min="2" max="200"'],['Abertura livre da porta (mm)','width','min="300" max="4000"']].map(([label,key,attrs])=>field(label,p+key,'number','',attrs)).join('')}${auxiliaryTravelField(i,j,groups[j])}${auxiliarySpeedField(i,j,groups[j])}${auxiliaryMotionField(i,j,groups[j],'acceleration')}${auxiliaryMotionField(i,j,groups[j],'jerk')}${select('Tipo de porta',p+'door',Object.fromEntries(Object.entries(DOORS).map(([key,v])=>[key,v.label])))}${[['Abertura da porta (s)','open'],['Fechamento da porta (s)','close'],['Entrada/saída por pessoa (s)','passenger'],['Partida adicional (s)','start']].map(([label,key])=>field(label,p+key,'number','','min="0"')).join('')}${checkField('Abertura antecipada de porta',p+'preOpeningEnabled','Aplicada ao cálculo FAB; premissa sem alteração dos tempos normativos.')}${g.preOpeningEnabled?field('Tempo de abertura antecipada (s)',p+'preOpening','number','Máximo igual ao tempo de abertura informado.','min="0" max="60"'):''}${field('PPH Limite do fabricante (partidas/h por elevador)',p+'startsLimit','number','0 = não informado.','min="0" max="100000" step="1"')}</div></article>`;
}
function auxiliaryResults(print=false,charts=true){
 if(isIso(state.draft))return isoAuxiliaryResults(print,charts);
 if(dirty||!result.auxiliary?.length)return '';
 return `<section class="below"><div class="section-heading"><h2>Resultados dos usos complementares</h2></div>${result.auxiliary.map((item,index)=>{
 if(item.excluded)return `<article class="card auxiliary-result"><h3>${esc(item.label)}</h3><p class="population-warning">${esc(item.basis)}</p></article>`;
 const r=item.results,s=item.study;
 return `<article class="card auxiliary-result"><h3>${esc(item.label)} · estudo separado</h3><p class="small-copy">${esc(USES[s.use].label)} · ${f(item.population,0)} pessoas · demanda ${f(r.rate*100)}% em 5 min.</p><div class="table-wrap"><table><thead><tr><th>Base</th><th>Demanda / 5 min</th><th>Capacidade / 5 min</th><th>Intervalo (s)</th><th>Mínimo estimado</th><th>Capacidade</th></tr></thead><tbody>${['normative','manufacturer'].map(key=>`<tr><td>${key==='normative'?(s.use==='auditorium'?'Ciclo NBR + premissas de auditório':'NBR 5665'):'Fabricante'}</td><td>${f(r.required)}</td><td>${f(r[key].capacity)}</td><td>${f(r[key].interval)}</td><td>${r.minimum[key].count}</td><td>${r[key].capacityPass?'Atende':'Não atende'}</td></tr>`).join('')}</tbody></table></div><p class="small-copy">${esc(item.basis)}</p><p class="minimum-alert">${esc(minimumMessage(s,r.minimum))}</p>${detailTable(r)}${startsSection(s,r,print)}${charts?`${travelCurvesSection(s,r,{print,prefix:"aux-"+index})}${performanceSection(s,r,{print,prefix:"aux-"+index})}${energySection(s,r,{print,prefix:"aux-"+index})}`:""}<details class="details-box" ${print?'open':''}><summary>Entradas, memória e avisos deste estudo</summary><div class="card-body">${s.groups.map((g,i)=>`<p class="small-copy">Grupo ${i+1}: ${g.count} elevador(es); lotação ${g.capacity}; paradas ${g.stops}; percurso ${f(g.travel)} m; velocidade ${f(g.speed)} m/s; porta ${esc(DOORS[g.door].label)}, ${g.width} mm; a ${f(g.acceleration)} m/s²; jerk ${f(g.jerk)} m/s³; abertura ${f(g.open)} s; fechamento ${f(g.close)} s; entrada/saída ${f(g.passenger)} s; partida ${f(g.start)} s.</p>`).join('')}${memory(r)}${escalatorResults(r.population.escalators)}<ul>${r.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div></details></article>`;
 }).join('')}</section>`;
}
function normExcerpts(){return `<div class="norm-excerpts"><h3>Transcrições dos itens utilizados</h3>${NORM_EXCERPTS.map(([item,text])=>`<div class="norm-excerpt"><strong>${esc(item)}</strong><blockquote>${esc(text)}</blockquote></div>`).join('')}<p class="small-copy">Textos da edição adotada no estudo; símbolos e quebras de linha organizados para leitura. Consulte e adquira a norma oficial no Catálogo ABNT.</p></div>`;}
function buildingForm(){const current=portal.clients.find(c=>c.id===state.clientRecordId);return `<div class="registration-block"><h3>Empresa cliente</h3><div class="fields"><div class="field wide"><label for="study-client-picker">Escolher cliente cadastrado</label><select id="study-client-picker" data-client-select ${portal.available&&!isReadOnly()?'':'disabled'}><option value="">Preencher os dados de um cliente</option>${[...portal.clients].sort((a,b)=>a.companyName.localeCompare(b.companyName,'pt-BR')).map(c=>`<option value="${esc(c.id)}" ${state.clientRecordId===c.id?'selected':''}>${esc(c.companyName)}</option>`).join('')}</select><small>${portal.available?'O mesmo cliente pode ser utilizado em vários projetos.':'Os clientes são carregados após conectar sua conta.'}</small></div>${field('Cliente · nome da empresa','client','text','','maxlength="200"')}${field('Contato da empresa cliente','customer.contact','text')}${field('Endereço da empresa cliente','customer.address','text')}${field('Telefone da empresa cliente','customer.phone','text')}${field('Email da empresa cliente','customer.email','email')}</div><div class="buttons">${button('save-study-client',current?.canEdit?'Atualizar cadastro do cliente':'Salvar cadastro do cliente','small','save',portal.available?'':'disabled')}${button('unlink-study-client','Novo cliente','small','plus')}${button('navigate','Ver clientes cadastrados','small','users','data-view="clients"')}</div><p class="small-copy">Salvar o cadastro permite reutilizar os contatos. Cada projeto mantém seus dados e os relatórios compartilhados preservam a versão original.</p></div><div class="registration-block"><h3>Identificação do projeto</h3><div class="fields">${field('Nome do estudo','name','text','','required maxlength="120"')}${field('Data do estudo','date','date')}${field('Edifício · nome do projeto','building','text')}${field('Endereço do projeto','address','text')}${field('Contato no endereço do projeto','projectDetails.contact','text')}${field('Telefone no endereço do projeto','projectDetails.phone','text')}${isIso(state.draft)?field('CNPJ do empreendimento / proprietário','isoConfig.projectCnpj','text','','maxlength="30"')+field('Data de aprovação do projeto','isoConfig.approvalDate','date'):''}</div></div><details class="details-box"><summary>Responsabilidade técnica e autoria do relatório</summary><div class="fields">${field('Proprietário','annex.owner','text')}${field('Autor do projeto','annex.author','text')}${field('Construtor','annex.builder','text')}${field('Engenheiro responsável','annex.engineer','text')}${field('Empresa responsável','annex.installer','text')}${field('Observações para o formulário','annex.notes','textarea')}</div></details>`;}

function timingWarnings(g,i){let computed;try{computed=recalculatePopulationAndStudies(state.draft);}catch{}const context=computed?.results.groupStudies?.find(c=>c.id===g.id),r=context?.results||computed?.results,study=r?.calculationStudy||context?.study||computed?.study;const required=[];const warnings=fleetCars(state.draft,g).map((car,j)=>{let reference=DOORS[car.door]?.time;if(isIso(state.draft))try{const d=isoDoor(car.width,car.door);reference=d.open+d.close;}catch{reference=null;}const k=study?.groups.findIndex(x=>(x.logicalGroupId||x.id)===g.id&&(!x.carNumbers||x.carNumbers.includes(j+1))),pph=k>=0?r.starts.rows[k]?.requiredPerCar:undefined;if(Number.isFinite(pph))required.push(pph);return reference&&g.open+g.close>reference?`<p class="population-warning">Elevador ${j+1}: abertura + fechamento ${f(g.open+g.close)} s acima da referência ${f(reference)} s ${isIso(state.draft)?'do documento ISO informado, tabela 8':'da NBR 5665, tabela 3'}. Tempos maiores podem reduzir a performance; confirme os dados do fabricante. A tabela é referência do cálculo normativo, não um limite universal de segurança.</p>`:'';}).join('');const pph=required.length?Math.max(...required):null;return warnings+(g.startsLimit===0?'<p class="population-warning">PPH do fabricante não informado. Confirmar capacidade de partidas com o fornecedor.</p>':Number.isFinite(pph)&&g.startsLimit<pph?`<p class="errors">Não atendimento: limite do fabricante ${f(g.startsLimit)} PPH inferior às ${f(pph)} partidas/h por elevador necessárias no cálculo.</p>`:'');}

function groupForm(){const i=Math.min(state.group,state.draft.groups.length-1),g=state.draft.groups[i],p='groups.'+i+'.',preview=probableStops(g,state.draft.trafficModel),r=preview.available?{stops:preview.value}:null;return `<div class="group-tabs" aria-label="Conjuntos de elevadores">${state.draft.groups.map((g,j)=>`<button type="button" data-action="group" data-index="${j}" class="${i===j?'active':''}">${esc(g.label)}</button>`).join('')}${button('add-group','Adicionar','small','plus',state.draft.groups.length>=MAX_GROUPS?'disabled':'')}</div>${fleetTable(state.draft,i,{esc,f})}<div class="group-title"><div><h3>${esc(g.label)}</h3>${button('copy-group','Copiar dados do grupo','small','copy')}<p>Organize os elevadores deste grupo. A tabela permite características individuais; os tempos de portas e movimento são individuais.</p></div>${state.draft.groups.length>1?button('remove-group','Remover','small danger','trash'):''}</div><div class="fields">${groupApplication(i)}${field('Nome do grupo',p+'label','text','Identifica o grupo no sistema, relatório e apresentação.','required maxlength="80"')}${field('Elevadores neste conjunto',p+'count','number','','required min="1" max="30"')}${field('Paradas (incluindo acesso)',p+'stops','number','Preenchido automaticamente pela matriz de pavimentos e atendimento.','readonly')}${travelField(g,i)}</div>${carTimingTable(state.draft,i,{esc,f})}<div class="field-note">Os tempos de fabricante são utilizados em um cálculo paralelo. Os parâmetros da NBR 5665 continuam independentes. Dimensões do projeto e do produto ficam na aba Parâmetros dimensionais. O catálogo registra configurações declaradas, sem certificação automática de conformidade.</div>`;}
function operationForm(){if(sharedReadOnly&&!result?.performance)return `<p class="small-copy">Parâmetros operacionais da versão histórica. Reabra e recalcule para produzir os gráficos atuais.</p><div class="fields">${select('Perfil registrado','operation.profile',{light:'Leve',moderate:'Moderado',heavy:'Pesado'})}${field('Fretado (%)','operation.charter')}${field('Almoço (%)','operation.lunch')}${field('Permanência (s)','operation.dwell')}</div>`;return performanceForm(state.draft,{field,select,button});}
function resultsAside(){if(isIso(state.draft))return isoResultAside(result?.calculationStudy||state.draft,dirty?null:result,isoHelpers());if(dirty)return `<div class="card"><div class="result-head"><h2>Resultados</h2><p>Parâmetros alterados</p></div><div class="stale">${icon('refresh')}<h3 style="margin-top:12px">Recalcule o estudo</h3><p>Os resultados anteriores foram retirados para evitar comparar dados de momentos diferentes.</p>${button('calculate','Calcular estudo completo','primary full','arrow')}</div></div>`;const r=result,s=result.calculationStudy||state.draft;const block=(a,title)=>`<div class="result-mode">${title}${badge(a.capacityPass,'Capacidade atende')}</div><div class="result-line"><span>Capacidade em 5 min</span><strong>${f(a.capacity)} <small>pessoas</small></strong></div><div class="result-line"><span>Intervalo ${!a.homogeneous?'estimado':''}</span><strong>${f(a.interval)} <small>s</small></strong></div>${r.limit===null?'<span class="badge neutral">Intervalo não exigido para apartamentos</span>':badge(a.intervalPass,'Intervalo atende',!a.homogeneous)}`;return `<div class="card"><div class="result-head"><h2>Fabricante × NBR 5665</h2><p>Mesmas entradas. Tempos independentes.</p></div><div class="result-main"><div class="minimum-alert ${s.commonService&&r.normative.count<r.minimum.normative.count?'minimum-insufficient':''}" role="status"><strong>Quantidade mínima de elevadores</strong><p>${esc(minimumMessage(s,r.minimum))}</p></div>${populationWarnings(s).map(w=>`<p class="population-warning">${esc(w)}</p>`).join('')}${r.parameterWarnings.length?`<div class="parameter-alert" role="status">${r.parameterWarnings.map(w=>`<p>${esc(w)}</p>`).join('')}</div>`:''}${r.motionWarnings.map(w=>`<div class="motion-summary ${w.severity}" role="status">${esc(w.message)}</div>`).join('')}${block(r.normative,s.use==='auditorium'?'CICLO NBR + PREMISSAS DO AUDITÓRIO':r.hasLowSpeed?'NBR + PREMISSA DE VELOCIDADE':'REFERÊNCIA NORMATIVA')}<div class="progress ${!r.normative.capacityPass?'fail':''}"><div style="width:${r.required>0?Math.min(100,r.normative.capacity/r.required*100):0}%"></div></div><div class="capacity-caption"><span>Demanda: ${f(r.required)}</span><span>${f(r.normative.margin)} de margem</span></div><div class="result-divider"></div>${block(r.manufacturer,'DADOS DO FABRICANTE')}<div class="result-divider"></div><div class="delta-box"><span>Diferença de capacidade<br>Fabricante sobre NBR</span><strong>${r.deltaPercent>=0?'+':''}${f(r.deltaPercent)}%</strong></div><p class="small-copy">${!s.commonService?'Soma informativa de conjuntos independentes. Prepare um estudo por zona.':!r.normative.homogeneous?'Intervalo consolidado é a estimativa ponderada por quantidade. Consulte os resultados por conjunto.':'Para tempos iguais, o intervalo consolidado é I = T / quantidade total.'} A análise cobre critérios de tráfego, sem certificar toda a instalação.</p></div></div><div class="card mini-card"><h3>${icon('book')}Premissas à vista</h3><p>Tráfego predominante de subida · população informada · lotação útil completa · adicional de 10% em T3 + T4.</p><div style="margin-top:12px">${button('show-assumptions','Ver memória e fontes','small','arrow')}</div></div><div class="card mini-card"><h3>${icon('lock')}Seu estudo é privado</h3><p>O acesso ao site é restrito ao proprietário. Os cenários ficam neste navegador. Exporte o JSON para guardar ou transferir seus estudos.</p></div>`;}
function detailTable(r=result){if(r.model==='iso8100')return isoResultsTable(r);return `<div class="table-wrap"><table><thead><tr><th>Conjunto</th><th class="number">Elevadores</th><th class="number">Paradas prováveis</th><th class="number">PPH NBR (partidas/h)</th><th class="number">PPH FAB (partidas/h)</th><th class="number">Capacidade NBR / 5 min</th><th class="number">Capacidade FAB / 5 min</th><th class="number">Intervalo de tráfego NBR (s)</th></tr></thead><tbody>${r.groups.map((g,i)=>`<tr><td><strong>${esc(g.label||'Grupo '+(i+1))}</strong><small>${g.count} unidade${g.count>1?'s':''}</small></td><td class="number">${g.count}</td><td class="number">${f(g.stops)}</td><td class="number">${f(3600*g.stops/g.normative.total)}</td><td class="number">${f(3600*g.stops/g.manufacturer.total)}</td><td class="number">${f(g.normative.capacity)}</td><td class="number">${f(g.manufacturer.capacity)}</td><td class="number">${f(g.normative.interval)}</td></tr>`).join('')}<tr class="total-row"><td><strong>Total / condição de atendimento</strong></td><td>${r.normative.count}</td><td>Não somável</td><td>${f(r.groups.reduce((n,g)=>n+3600*g.stops*g.count/g.normative.total,0))}</td><td>${f(r.groups.reduce((n,g)=>n+3600*g.stops*g.count/g.manufacturer.total,0))}</td><td>${f(r.normative.capacity)} · ${r.normative.capacityPass===null?'Sem conclusão':r.normative.capacityPass?'Atende':'Não atende'}</td><td>${f(r.manufacturer.capacity)} · ${r.manufacturer.capacityPass===null?'Sem conclusão':r.manufacturer.capacityPass?'Atende':'Não atende'}</td><td>${f(r.normative.interval)} · ${r.normative.intervalPass===null?'Sem conclusão':r.normative.intervalPass?'Atende':'Não atende'}</td></tr></tbody></table></div>`;}
function simulationPanel(){if(dirty||!result)return '';return performanceSection(state.draft,result)+energySection(state.draft,result);}
function studyPage(){return workflowHead('Cadastro','Escolha um cliente ou registre seus dados. Depois, identifique o projeto.')+`<section class="card card-body registration-card" aria-labelledby="building-title"><h2 id="building-title">Cliente e projeto</h2>${buildingForm()}</section><details class="technical-details"><summary>Importar estudo ou carregar exemplo</summary><div class="buttons">${button('import','Importar JSON','','upload')}${button(portal.available?'new-cloud-study':'new-blank-study','Novo estudo com campos vazios','','plus')}${button('load-example','Carregar exemplo','','refresh')}</div></details>`+workflowFooter();}
function workflowHead(title,subtitle,actions=''){const index=STUDY_STEPS.findIndex(s=>s.view===state.view);return head(title,subtitle,actions||button('save-project','Salvar projeto','','save',portal.available&&!isReadOnly()?'':'disabled'))+`<div class="study-context"><div><span class="eyebrow">ESTUDO ATUAL</span><strong>${esc(state.draft.name)}</strong><span>${esc(MODEL_LABELS[state.draft.trafficModel||'nbr5665'])}</span></div><div><span class="step-badge">Etapa ${index+1} de 5</span><span id="study-status" class="study-status ${dirty?'pending':'ready'}" role="status">${dirty?'Cálculo pendente':'Resultados atualizados'}</span></div></div>`;}
function workflowFooter(){const i=STUDY_STEPS.findIndex(s=>s.view===state.view);return `<div id="calculation-readiness">${readinessHtml(state.draft,esc,f,state.view)}</div><nav class="workflow-footer" aria-label="Avançar ou voltar no estudo"><span id="save-info" class="save-info">${portal.available?(portal.project.id?'Projeto salvo na conta':'Salve o projeto para continuar depois'):'Rascunho neste navegador'}</span><div class="buttons">${i>0?button('workflow-step','Voltar','','',`data-view="${STUDY_STEPS[i-1].view}"`):''}${i<4?button('workflow-step','Continuar: '+STUDY_STEPS[i+1].title,'primary','arrow',`data-view="${STUDY_STEPS[i+1].view}"`):''}</div></nav>`;}
function scheduleForm(){state.draft.operation.schedule={...defaultSchedule(),...state.draft.operation.schedule};return `<section class="card card-body"><h2>Expediente e equipamento existente</h2>${checkField('Utilizar expediente nos perfis e no consumo','operation.schedule.enabled')}${state.draft.operation.schedule.enabled?`<div class="fields">${field('Início das atividades','operation.schedule.start','time')}${field('Fim do expediente','operation.schedule.end','time')}${field('Início do almoço','operation.schedule.lunchStart','time')}${field('Fim do almoço','operation.schedule.lunchEnd','time')}${field('Utilização média do PPH de pico (%)','operation.schedule.peakUtilizationPercent','number','Hipótese para projetar partidas durante o expediente. 100% mantém o pico durante todo o dia.','min="0.1" max="100"')}</div>`:''}<div class="fields">${select('Tecnologia existente','energy.baseline',Object.fromEntries(Object.entries(ENERGY_TECHNOLOGIES).map(([k,t])=>[k,t.label])))}${select('Tecnologia proposta no cenário','energy.comparisonTechnology',Object.fromEntries(Object.entries(ENERGY_TECHNOLOGIES).map(([k,t])=>[k,t.label])))}${select('Base das partidas no consumo','energy.startsSource',{traffic:'PPH calculado × expediente × utilização',manual:'Partidas diárias declaradas'})}${state.draft.energy.startsSource==='manual'?field('Número de partidas diárias por elevador','energy.dailyStarts','number','Partidas diárias declaradas pelo usuário; não são partidas por hora.','min="0" max="100000" step="1"'):''}</div><p class="small-copy">O expediente deve ocorrer no mesmo dia, em horários múltiplos de 5 minutos. Perfis estimados são distribuídos entre os horários; medições mantêm as contagens e a janela real. Consumo fora do expediente não é incluído.</p></section>`;}
function parametersPage(){const h={...isoHelpers(),travelPreview:()=>''},transport=transportOptions(state.draft);if(state.parameterTab==='escalators'&&!escalatorTabAvailable(state.draft)||state.parameterTab==='walkways')state.parameterTab='traffic';return workflowHead('Parâmetros de cálculo','Defina a base do estudo e configure os grupos de elevadores.')+modelSelector()+scheduleForm()+transportQuestion(state.draft,{esc,button})+`<section class="card card-body">${state.draft.floorTable?floorTableHtml(state.draft,esc,f):'<p>Versão histórica sem tabela de pavimentos cadastrada.</p>'}</section>`+`<section class="card card-body"><h2>Edifício e critérios</h2><div class="fields"></div><p class="field-note">Aviso: Os conjuntos atendem as mesmas paradas, hall, acesso principal e uso. Confira essa condição. Este aviso não bloqueia o cálculo; destinos diferentes são organizados pela matriz de pavimentos e atendimento.</p></section>${isIso(state.draft)?`<details class="card technical-details"><summary>Critérios específicos do modelo ISO</summary>${isoConfiguration(state.draft,h)}</details>`:''}<nav class="analysis-tabs">${button('parameter-tab','Dados dos Elevadores do estudo',!['dimensions','escalators','walkways'].includes(state.parameterTab)?'active':'','',"data-tab=\"traffic\"")}${button('parameter-tab','Parâmetros dimensionais',state.parameterTab==='dimensions'?'active':'','',"data-tab=\"dimensions\"")}${escalatorTabAvailable(state.draft)?button('parameter-tab','Escadas e esteiras rolantes',state.parameterTab==='escalators'?'active':'','','data-tab="escalators"'):''}${portal.project.canManage||['admin','director'].includes(portal.user?.role)?button('open-dimensional-catalog','Consultar catálogo dimensional','','book'):''}</nav>${supplyConditionForm(state.draft,{field,select})}${state.parameterTab==='escalators'?`<section class="card card-body">${escalatorFloorNotice(state.draft)?`<p class="errors escalator-disconnected" role="alert">${esc(escalatorFloorNotice(state.draft))}</p>`:''}${escalatorForm(currentPopulation())}${walkwayForm(state.draft,{esc,button,field})}</section>`:state.parameterTab==='walkways'?walkwayForm(state.draft,{esc,button,field}):state.parameterTab==='dimensions'?siteDimensionsForm(state.draft,{field,select}):`<section class="card card-body below"><h2>Dados dos Elevadores do estudo</h2>${isIso(state.draft)?isoGroupForm(state.draft,state.group,h):groupForm()}</section>`}${state.draft.populationCalc.rows.filter(row=>row.mode==='external').map(row=>{const i=state.draft.populationCalc.rows.indexOf(row);return `<details class="card technical-details"><summary>Elevadores do estudo separado · ${esc(row.label)}</summary><div class="card-body">${row.groups.map((g,j)=>auxiliaryGroup(i,j)).join('')}<div class="buttons">${button('add-auxiliary-group','Adicionar grupo','small','plus',`data-index="${i}" ${row.groups.length>=20?'disabled':''}`)}</div></div></details>`;}).join('')}`+workflowFooter();}
function populationPage(){return workflowHead('Cálculo populacional','Inclua os ambientes de cada andar. A população é atualizada durante o preenchimento.')+populationForm()+workflowFooter();}
function analysisEmpty(){return `<div class="analysis-empty"><h3>Resultados aguardam cálculo</h3><p>Após revisar os parâmetros e a população, calcule o estudo completo para apresentar os gráficos atualizados.</p>${state.view==='traffic'?'':button('workflow-step','Ir para cálculo de tráfego','primary','arrow','data-view="traffic"')}</div>`;}
function graphSections(kind){if(dirty||!result)return analysisEmpty()+(kind==='travel'?`<section class="card card-body"><h2>Prévia do grupo em edição</h2><div class="group-tabs">${state.draft.groups.map((g,i)=>button('group',g.label,state.group===i?'active':'','',`data-index="${i}"`)).join('')}</div>${travelPreview()}</section>`:'');const renderPart=(s,r,prefix)=>kind==='energy'?energySection(s,r,{prefix}):kind==='travel'?travelCurvesSection(s,r,{prefix}):performanceSection(s,r,{prefix});return (result.groupSeparated?(kind==='operation'&&state.draft.operation.profile==='measured'?`<details class="card technical-details" open><summary>Medições globais · observação consolidada, sem conclusão comum</summary>${renderPart(state.draft,result,'main')}</details>`:'')+result.groupStudies.map((c,i)=>`<section class="card card-body"><h2>${esc(c.label)}</h2><p>${esc(c.basis)}</p>${c.results.zoneSeparated?c.results.zones.map((z,j)=>renderPart(z.study,z.results,'logical-'+i+'-zone-'+j)).join(''):renderPart(c.study,c.results,'logical-'+i)}</section>`).join(''):result.zoneSeparated?result.zones.map((z,i)=>`<section class="card card-body"><h2>${esc(z.label)} · andares ${z.floorMarks.map(esc).join(', ')}</h2>${renderPart(z.study,z.results,'zone-'+i)}</section>`).join(''):renderPart(state.draft,result,'main'))+(result.auxiliary||[]).filter(i=>!i.excluded).map(item=>{const i=result.auxiliary.indexOf(item);return `<details class="card technical-details"><summary>${esc(item.label)} · estudo separado</summary>${renderPart(item.study,item.results,'aux-'+i)}</details>`;}).join('');}
function performancePage(){const tab=['operation','energy','travel'].includes(state.analysisTab)?state.analysisTab:'operation';return workflowHead('Gráficos de performance e economias','Compare o atendimento, o consumo e as viagens em painéis separados.')+`<nav class="analysis-tabs" aria-label="Tipo de gráfico">${[['operation','Atendimento'],['energy','Energia e potência'],['travel','Viagens']].map(([key,label])=>button('analysis-tab',label,tab===key?'active':'','',`data-tab="${key}" ${tab===key?'aria-current="page"':''}`)).join('')}</nav>${!isReadOnly()&&tab!=='travel'?`<details class="card technical-details" ${dirty?'open':''}><summary>${tab==='energy'?'Configurar estimativa de consumo':'Configurar perfis e medições'}</summary><div class="card-body">${tab==='energy'?energyForm(state.draft,{field,select}):operationForm()}</div></details>`:''}<div id="analysis-output">${tab==='energy'&&!dirty?procurementSummary(portal.procurement):''}${tab==='energy'&&portal.procurement?.offers?.length&&!dirty?'':graphSections(tab)}</div>`+workflowFooter();}
function reportActions(){return `<section class="card card-body report-actions-bottom"><h2>Relatório e apresentação</h2><div class="buttons">${button('save-scenario','Salvar cenário','','save')}${button('print','Imprimir / Salvar PDF','','print')}${button('download-report','Baixar relatório HTML','','download')}${button('download-pptx','Gerar PowerPoint editável','','download')}${button('share-study','Compartilhar / solicitar autorização','','lock')}${button('export','Exportar dados','','download',portal.user?.exportApproved?'':'disabled')}${button('import','Importar dados','','upload')}</div></section>`;}
function trafficPage(){const r=dirty?null:result,h=isoHelpers();return workflowHead('Cálculo de tráfego','Calcule a população e todos os estudos juntos. Depois, emita o relatório.',isReadOnly()?'':button('calculate','Calcular estudo completo','primary','compare')+button('save-project','Salvar projeto','','save',portal.available?'':'disabled'))+sharePanel(portal,reportReady(dirty,result))+`${errors.length?`<div class="errors" role="alert"><strong>Revise os dados antes de calcular</strong><ul>${errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="buttons">${button('workflow-step','Parâmetros','small','','data-view="parameters"')}${button('workflow-step','População','small','','data-view="population"')}${button('workflow-step','Perfis e energia','small','','data-view="performance"')}</div></div>`:''}<div id="metrics">${metrics()}</div><div id="traffic-results">${r?`<div class="traffic-grid"><section>${r.groupSeparated?'<div class="card card-body"><h2>Atendimento por grupo</h2><p>Cada grupo é calculado com seus elevadores e sua população atendida. Não há conclusão global pela soma dos grupos.</p></div>':r.zoneSeparated?'<div class="card card-body"><h2>Grupos com atendimento por zonas</h2><p>Confira abaixo os critérios e resultados de cada zona. A soma de capacidades é informativa e não garante atendimento de todas as zonas.</p></div>':isIso(state.draft)?isoResultAside(r.calculationStudy||state.draft,r,h):resultsAside()}</section><section class="card card-body"><h2>Resultados por conjunto</h2>${isIso(state.draft)?isoResultsTable(r):detailTable()}<details class="details-box"><summary>Memória do cálculo</summary>${isIso(state.draft)?isoMemory(r):memory()}</details><div class="buttons">${button('workflow-step','Ver gráficos','small','compare','data-view="performance"')}${button('export','Exportar estudo','small','download',portal.user?.exportApproved?'':'disabled')}</div></section></div><details class="card technical-details"><summary>Partidas por hora</summary>${isIso(state.draft)?isoStartsSection(r):startsSection(state.draft,r)}</details>${zonesSection(r)}${auxiliaryResults(false,false)}<details class="card technical-details annex-preview"><summary>Conferir formulário ${isIso(state.draft)?'ISO':'Anexo A da NBR 5665'}</summary><div class="card-body">${isIso(state.draft)?(r.groupSeparated?r.groupStudies.map(c=>isoAnnex(c.study,c.results,c.label)).join(''):r.zoneSeparated?r.zones.map(z=>isoAnnex(z.study,z.results,z.label)).join(''):isoAnnex(state.draft,r)):annexPages(state.draft,r)}</div></details>${procurementSummary(portal.procurement)}${reportActions()}`:analysisEmpty()}</div>`+workflowFooter();}

function compareTable(scenarios){if(scenarios.some(x=>isIso(x.study)))return modelCompareTable(scenarios);const rr=scenarios.map(s=>({name:s.study.name,study:s.study,result:calculateStudy(s.study)}));const rows=[['População',x=>f(x.study.population,0)],['Unidades',x=>f(x.result.normative.count,0)],['Demanda em 5 min',x=>f(x.result.required)],['Capacidade NBR / 5 min',x=>f(x.result.normative.capacity)],['Capacidade FAB / 5 min',x=>f(x.result.manufacturer.capacity)],['Intervalo NBR (s)',x=>f(x.result.normative.interval)],['Intervalo FAB (s)',x=>f(x.result.manufacturer.interval)],['Partidas necessárias / h · total',x=>f(x.result.starts?.totalRequired)],['Máximo de partidas / h · total',x=>f(x.result.starts?.totalMaximum)],['Máximo de intervalo (s)',x=>x.result.limit===null?'Não exigido':f(x.result.limit,0)],['Capacidade NBR',x=>badge(x.result.normative.capacityPass)],['Intervalo NBR',x=>x.result.limit===null?'Não exigido':badge(x.result.normative.intervalPass,'Atende',!x.result.normative.homogeneous)],['Precisão',x=>'Precisão integral de interpolação'],['Serviço comum',x=>x.study.commonService?'Declarado':'Zonas separadas']];return `<div class="table-wrap"><table><thead><tr><th>Indicador</th>${rr.map(x=>`<th>${esc(x.name)}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><td><strong>${label}</strong></td>${rr.map(x=>`<td>${fn(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function scenariosPage(){if(state.scenarios.some(x=>isIso(x.study)))return modelScenariosPage();let content=head('Compare seus cenários','Guarde alternativas e veja o efeito de velocidade, lotação e quantidade de elevadores.',button('navigate-study','Voltar ao estudo','','arrow')+button('save-scenario','Salvar cenário atual','primary','save',dirty?'disabled':''));if(!state.scenarios.length)return content+`<div class="card empty">${icon('compare')}<h2>Seu primeiro comparativo começa aqui</h2><p>Calcule um estudo e salve o cenário. Depois altere os parâmetros e salve uma alternativa. Os resultados aparecem lado a lado.</p>${button('seed-scenarios','Comparar exemplo e alternativa','primary','plus')}</div>`;return content+`<div class="scenario-grid">${state.scenarios.map(s=>{const r=calculateStudy(s.study);return `<article class="card scenario"><div class="eyebrow">${f(r.normative.count,0)} ELEVADORES · ${s.study.groups.length} CONJUNTOS</div><h3>${esc(s.study.name)}</h3><p class="small-copy">${esc(USES[s.study.use].label)}<br>Salvo em ${esc(new Date(s.savedAt).toLocaleString('pt-BR'))}</p>${badge(r.normative.capacityPass,'Capacidade atende')}<div class="summary-strip"><div><span>Capacidade NBR</span><strong>${f(r.normative.capacity)}</strong></div><div><span>Intervalo NBR</span><strong>${f(r.normative.interval)} s</strong></div><div><span>População</span><strong>${f(s.study.population,0)}</strong></div></div><div class="buttons">${button('load-scenario','Abrir','small','arrow',`data-id="${esc(s.id)}"`)}${button('duplicate-scenario','Criar alternativa','small','copy',`data-id="${esc(s.id)}"`)}${button('delete-scenario','Excluir','small danger','trash',`data-id="${esc(s.id)}"`)}</div></article>`;}).join('')}</div><section><div class="section-heading"><div><h2>Comparação lado a lado</h2><p>Cenários salvos, recalculados pelo mesmo motor ${ENGINE_VERSION}.</p></div>${button('export-comparison','Exportar CSV','small','download')}</div><div class="card">${compareTable(state.scenarios)}<div class="footnote">Compare alternativas com a mesma população, uso e premissas de serviço. O intervalo para tempos de ciclo diferentes é uma estimativa por quantidade. Cenários armazenados somente neste navegador.</div></div></section>`;}
function methodology(){return `<div class="method-list">${[
['Ciclo normativo','T1 = 2 × percurso / velocidade. T2 = N × tempo de aceleração / 2. T3 = N × tempo de portas. T4 = lotação × tempo por passageiro. <code>T = T1 + T2 + 1,1 × (T3 + T4)</code>. NBR 5665, 6.1.'],
['Paradas prováveis','<code>N = p − (p − 1) × ((p − 2) / (p − 1))^c</code>. p inclui o acesso; c é a lotação útil. NBR 5665, 6.2. A precisão integral mantém N completo; duas casas são usadas apenas na apresentação.'],
['Tempos normativos','Tabela 2: 0,63/0,75 m/s → 2,5 s; 1/1,25 → 3 s; 1,5 → 3,5 s; 1,75 → 4 s; 2 → 4,5 s; 2,5 → 5,5 s; acima → 6 s. Precisão integral interpola entre pontos. Para velocidades positivas abaixo de 0,63 m/s, adota-se 2,50 s como premissa explicitamente identificada, não como valor tabelado na norma. Tabela 3: central 3,9 s, lateral 5,5 s e eixo vertical 6 s. Tabela 4: porta menor que 1.100 mm → 2,4 s/pessoa; demais → 2 s/pessoa.'],
['Conferência do percurso','<code>Percurso de referência = (paradas − 1) × 2,80 m</code>. Quando o percurso informado é menor, o campo e o aviso ficam vermelhos. O alerta se atualiza ao editar percurso ou paradas, sem bloquear o cálculo. Esta regra foi definida pelo usuário como critério de projeto, sem atribuição à NBR 5665.'],
['Capacidade','<code>Ct = 300 × lotação / T</code> por elevador. Para cada conjunto, multiplicar pela quantidade; <code>CT = Σ Ct</code> do serviço comum. Exigência mínima = população × percentual do uso. NBR 5665, 5.2.1, 6.3 e 6.4. Sem arredondar a capacidade antes de comparar.'],
['Intervalo','Cada conjunto: <code>I = T / ne</code>. Consolidado de ciclos diferentes: <code>Σ(T × quantidade) / quantidade total²</code>. Para ciclos iguais, coincide com T/ne. Para ciclos diferentes, é premissa aproximada de consolidação. Tabela 6: 1/2/3 elevadores → 80/60/50 s. Quatro ou mais: 40 s em escritórios e 45 s nos demais usos listados. Apartamentos exclusivos têm exceção (6.5.2).'],
['Fabricante','Tempos de abertura e fechamento são somados automaticamente. Aceleração/retardamento estimados por <code>2 × (v/a + a/j)</code>, com os parâmetros de movimento informados. Quando v &lt; a²/j, usa-se <code>4 × √(v/j)</code>. Partida adicional é somada uma vez por ciclo. A expressão não representa trajeto real com distâncias entre pavimentos.'],
['Alerta de aceleração','Critérios de alerta definidos para este estudo: campo amarelo quando <code>1,00 &lt; a ≤ 1,60 m/s²</code>, e vermelho quando <code>a &gt; 1,60 m/s²</code>. Acelerações acima de 1,00 m/s² podem causar desconforto na viagem.'],
['Alerta de jerk','Campo amarelo quando jerk > 1,20 m/s³ até 2,50 m/s, ou > 1,60 m/s³ acima de 2,50 m/s. Aviso de desconforto em viagem conforme os parâmetros de conforto definidos para o estudo.'],
['Operação em 1 hora','Perfis de operação: 80% (leve/moderado) e 95% (pesado). Complemento de fretado = 100% − valor informado. Pesos são normalizados para somar 100%. Capacidade operacional = Σ[300 × lotação × unidades / (T + N × permanência)]. Fila por bloco = máximo(0, fila anterior + demanda − capacidade).'],
['Escadas rolantes','Referências atuais de segurança: ABNT NBR 16734-1:2022 e Parte 2:2023 para equipamentos existentes. Capacidade horária documentada pelo fabricante, separada por sentido. Capacidade na janela = capacidade horária × minutos / 60 × utilização / 100. A demanda acumula os pavimentos dependentes da ligação contínua. Par, configuração técnica e capacidade operacional precisam de confirmação. A exclusão populacional utiliza NBR 5665, 5.1.6. Itens numéricos da edição atual aguardam validação no texto oficial.'],
['Usos complementares','NBR 5665, 5.1.7: registrar exclusões de áreas de apoio de uso exclusivo e preservar paradas e percurso. Demandas externas de garagem e restaurante recebem população, elevadores e resultados separados; usar o percentual correspondente ao uso (5.2.2). Garagem: rampas sem manobrista, 1,4 pessoa/vaga e 10% em 5 min. Restaurante: 1 pessoa/1,5 m² e 6% em 5 min. Não duplicar a população na composição principal. Auditórios: população por assentos e demanda/intervalo informados como premissas; nenhum percentual específico de auditórios é atribuído às normas fornecidas.'],
['Composição, andar e população','A indicação identifica somente o ambiente. A posição organiza a composição no estudo e é independente do andar atendido. Vários ambientes podem atender o mesmo andar; o resumo soma suas populações e ordena os andares pelo nível físico. Em cada ambiente, compara-se a população calculada líquida com a declarada e adota-se o maior valor. Para cada andar e estudo, somam-se uma única vez os valores adotados dos seus ambientes. Calculada e declarada do mesmo ambiente não são somadas entre si. Declarações iguais em ambientes distintos representam parcelas próprias. Exemplo: 40 e 20 calculadas totalizam 60; declarar 80 no primeiro ambiente resulta em 80 + 20 = 100; declarar 50 resulta em 50 + 20 = 70; declarar 30 mantém 40 + 20 = 60. A declaração é uma premissa do usuário, não uma fórmula normativa. A população adotada entra na verificação de capacidade das escadas rolantes. O andar de acesso confirmado e os usos exclusivos mantêm suas exclusões, com a população bruta na memória. A NBR 16858-3:2022, 5.4.2.3.2 a), permite caracteres consistentes com a nomenclatura do edifício e prefere −2, −1, 0, 1, 2 etc. Esse aviso se refere ao andar servido, não à posição interna da composição. Todo cálculo completo recalcula primeiro a população.'],
['Partidas por hora','Indicador operacional complementar: uma partida é cada saída, incluindo retorno ao acesso. Demanda horária equivalente = 12 × demanda em 5 min. Demanda entre grupos em serviço comum é distribuída pela capacidade FAB. Necessárias por elevador = demanda do grupo / lotação × N / quantidade. Distância média = 2 × percurso / N. Máximo pelo tempo = 3.600 / tempo médio entre partidas, com movimento ideal limitado por velocidade, aceleração, jerk e distância; portas, passageiros, adicional de 10%, tempo de ciclo rateado e permanência adicional. Um limite FAB informado restringe o máximo adotado. Não substitui análise térmica, despacho real, capacidade ou intervalo do estudo.'],
['Escopo','Escadas: referências atuais identificadas em 13/10/2026; cálculos de capacidade usam dados documentados do fabricante. Tráfego de elevadores: edição da NBR 5665 adotada no projeto; sua aplicabilidade deve ser conferida. Uso misto e zoneamento precisam de estudos específicos. Não avalia toda a NBR 16858-3, áreas de cabina, caixa, acessibilidade completa, catálogo de fabricante ou resgate/evacuação. O estudo exige revisão do responsável técnico antes de uso profissional.']
].map(([title,copy])=>`<div class="method-item"><strong>${title}</strong><p>${copy}</p></div>`).join('')}</div>`;}
function memory(r=result){if(r?.model==='iso8100')return isoMemory(r);if(dirty)return '<p class="small-copy">Recalcule o estudo para ver os componentes atualizados.</p>';return `<div class="table-wrap"><table><thead><tr><th>Grupo / base</th><th class="number">T1 (s)</th><th class="number">T2 (s)</th><th class="number">T3 (s)</th><th class="number">T4 (s)</th><th class="number">10% (T3+T4)</th><th class="number">Partida (s)</th><th class="number">Total (s)</th></tr></thead><tbody>${r.groups.flatMap((g,i)=>['normative','manufacturer'].map(key=>`<tr><td>Grupo ${i+1} · ${key==='normative'?'NBR':'FAB'}</td>${['t1','t2','t3','t4','additional','start','total'].map(k=>`<td class="number">${f(g[key][k])}</td>`).join('')}</tr>`)).join('')}</tbody></table></div>`;}
function assumptionsPage(){if(isIso(state.draft))return isoAssumptionsPage();return head('Premissas e memória de cálculo','Critérios, fórmulas e memória dos parâmetros adotados.',button('navigate-study','Voltar ao estudo','','arrow')+button('show-reference','Verificação de conteúdo','small','book'))+`<div class="source-grid">${SOURCES.map(source=>`<article class="card source"><h3>${esc(source.title)}</h3><div class="location">${esc(source.location)}</div><p>${esc(source.detail)}</p></article>`).join('')}</div><section class="card"><div class="card-head"><h2>Como o cálculo funciona</h2></div>${methodology()}<div class="card-body">${calculationExplanation()}${normExcerpts()}</div></section><section class="below card"><div class="card-head"><h2>Memória populacional</h2></div><div class="card-body">${populationMemory()}</div></section><section class="below card"><div class="card-head"><h2>Memória do estudo atual</h2></div>${memory()}${!dirty?startsSection(state.draft,result):''}${!dirty?`<div class="footnote">${result.warnings.map(w=>`<p>${esc(w)}</p>`).join('')}</div>`:''}</section><section class="below card"><div class="card-head"><h2>Validação dos cálculos</h2><span class="pill">${validation?.passed?`${validation.passed} verificações aprovadas`:'Conferências automatizadas'}</span></div><div class="card-body"><p>Componentes de ciclo, exemplos do anexo B, ocupação, descontos, população editada, dimensionamento mínimo, importação, cenários e controles da interface.</p><p class="small-copy">${esc(validation?.verificationLimit||'Validação automatizada dos cálculos e eventos da interface; conferência visual em navegador indisponível.')}</p></div></section>`;}
function referenceTable(headers,rows){return `<div class="table-wrap reference-table"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(value=>`<td>${typeof value==='number'?f(value,Number.isInteger(value)?0:2):esc(value)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function referencePage(){if(isIso(state.draft))return isoAssumptionsPage(true);const table5=[[3,17],[18,32],[33,37]].map(([lo,hi])=>{const capacities=Array.from({length:hi-lo+1},(_,i)=>i+lo);return `<h4>Lotação de ${lo} a ${hi} passageiros</h4>${referenceTable(['Paradas',...capacities.map(c=>String(c))],Array.from({length:47},(_,i)=>{const p=i+2;return [p,...capacities.map(c=>p-(p-1)*((p-2)/(p-1))**c)];}))}`;}).join('');return head('Verificação de conteúdo','NBR 5665:1983 e referências atuais de segurança das escadas rolantes.',button('show-assumptions','Premissas e memória','','arrow'))+`<div class="abnt-purchase"><h2>Adquira ou contrate o acesso à norma oficial pela ABNT</h2><p>Pesquise “NBR 5665”, “NBR 16734-1” e “NBR 16734-2” no Catálogo ABNT e confira a edição aplicável ao seu projeto. Esta página organiza o conteúdo para verificação do estudo e não fornece o PDF oficial.</p><a class="btn primary" href="${ABNT_CATALOG}" target="_blank" rel="noopener noreferrer">Consultar e adquirir pela ABNT</a></div><section class="card card-body">${normExcerpts()}<h3>Escadas rolantes · referências atuais</h3><p>${esc(ESCALATOR_REFERENCE_HELP)}</p><h3>Tabela enviada pelo proprietário</h3><p>${esc(ESCALATOR_TABLE_SOURCE)}</p>${referenceTable(['Degrau (mm)','0,50 m/s','0,65 m/s','0,75 m/s'],ESCALATOR_TABLE)}<p>Capacidades horárias também podem ser documentadas pelo fabricante. A antiga expressão permanece fora da base normativa ativa. A tabela agora enviada pelo proprietário pode ser selecionada explicitamente como premissa do estudo.</p></section><section class="card reference-content below">${REFERENCE_SECTIONS.map(([title,text])=>`<details class="reference-section"><summary>${esc(title)}</summary><p>${esc(text)}</p></details>`).join('')}</section><section class="card below"><details class="reference-section"><summary>Tabela 1 · Lotação, carga e área útil de cabina</summary><p>Valores da edição adotada para consulta. Colunas de carga histórica em N e kgf, como identificadas na tabela.</p>${referenceTable(['Pessoas','N','kgf','Área mínima (m²)','Área média (m²)','Área máxima (m²)'],CABIN_TABLE)}</details><details class="reference-section"><summary>Tabelas 2, 3 e 4 · Tempos utilizados</summary>${referenceTable(['Velocidade (m/s)','Aceleração e retardamento (s)'],[[.63,2.5],[.75,2.5],[1,3],[1.25,3],[1.5,3.5],[1.75,4],[2,4.5],[2.5,5.5],['Acima de 2,50',6]])}<p>Velocidades intermediárias admitem interpolação. Abaixo de 0,63 m/s, o tempo do protótipo é uma premissa explicitamente indicada no estudo.</p>${referenceTable(['Tipo de porta','Abertura e fechamento (s)'],[['Central',3.9],['Lateral',5.5],['Eixo vertical',6]])}${referenceTable(['Abertura livre (m)','Entrada e saída por passageiro (s)'],[['Menor que 1,10',2.4],['A partir de 1,10',2]])}</details><details class="reference-section"><summary>Tabela 5 · Paradas prováveis calculadas pela expressão corrigida</summary><p>Matriz para 2 a 48 paradas e lotação de 3 a 37 passageiros. As casas são arredondadas apenas para leitura.</p>${table5}</details><details class="reference-section"><summary>Tabela 6 · Intervalos máximos</summary>${referenceTable(['Quantidade','Uso','Máximo (s)'],[[1,'Geral',80],[2,'Geral',60],[3,'Geral',50],['4 ou mais','Escritórios de entidade única e escritórios em geral/consultórios',40],['4 ou mais','Hospitais, hotéis, escolas, lojas, garagens e restaurantes',45]])}<p>Exceção: elevadores que atendem exclusivamente apartamentos não estão sujeitos à exigência de intervalo da seção 6.5.2.</p></details></section>`;}

function subscriptionPage(){return licensePage(portal);}
