function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function safeName(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'_').slice(0,70)||'Estudo';}
function csvCell(v){let text=String(v??'');if(/^[=+@-]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';}
function exportStudy(){if(!reportReady(dirty,result)){toast('Calcule o estudo completo antes de exportar.');return;}download(safeName(state.draft.name)+'.json',JSON.stringify({schemaVersion:1,engineVersion:ENGINE_VERSION,exportedAt:new Date().toISOString(),study:state.draft,results:result,simulation:result.performance,sources:isIso(state.draft)?[{title:'Documento N69 · base da opção ISO8100',detail:ISO_PROVENANCE}]:SOURCES},null,2),'application/json');toast('Estudo exportado. O JSON pode ser importado novamente.');}
function exportComparison(){if(state.scenarios.some(x=>isIso(x.study)))return exportModelComparison();const rows=[['Cenário','População','Elevadores','Demanda 5 min','Capacidade NBR 5 min','Capacidade FAB 5 min','Intervalo NBR s','Intervalo FAB s','Serviço comum','Método','Partidas necessárias h total','Máximo partidas h total']];for(const x of state.scenarios){const r=calculateStudy(x.study);rows.push([x.study.name,x.study.population,r.normative.count,r.required,r.normative.capacity,r.manufacturer.capacity,r.normative.interval,r.manufacturer.interval,x.study.commonService?'Sim':'Não',x.study.method,r.starts?.totalRequired??'',r.starts?.totalMaximum??'']);}download('Comparacao_de_cenarios.csv','\uFEFF'+rows.map(row=>row.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Comparação exportada em CSV.');}
function renderPrint(){if(portal.project.licenseLocked)return;if(isBasic(state.draft)){if(reportReady(dirty,result))$('#print-report').innerHTML=basicReport(state.draft,result,portal.reportProfile||portal.profile);else $('#print-report')?.replaceChildren();return;}if(result?.model==='iso8100'&&reportReady(dirty,result)){renderIsoPrint();return;}if(!reportReady(dirty,result)){ $('#print-report')?.replaceChildren();return;}const s=result.calculationStudy||state.draft,r=result;const body=`<div class="report-head"><div><div class="eyebrow">SilSec · PROTÓTIPO PRIVADO</div><h1>Estudo de tráfego em elevadores</h1></div><div>${esc(s.date)}<br>Motor ${esc(r.engineVersion||ENGINE_VERSION)}</div></div><h2>${esc(s.name)}</h2>${firstPageIdentification(s)}${floorTableReport(s,esc,f)}${dimensionsReport(s,esc,f,r.dimensionReferences)}${transportReport(s,esc,f)}${fleetMassMemory(s,{esc,f})}${carTimingMemory(s,{esc,f})}${zonesSection(r,true)}${sharedReadOnly&&r.engineVersion!==ENGINE_VERSION?'<p class="population-warning">Versão histórica: resultados e população preservados no motor original. As referências atuais e orientações desta página não revalidam esse cálculo. Reabra e recalcule o projeto para emitir uma versão atualizada.</p>':''}<p>Cliente: ${esc(s.client||'Não informado')}<br>Edifício: ${esc(s.building||'Não informado')}<br>Endereço: ${esc(s.address||'Não informado')}<br>Uso: ${esc(USES[s.use].label)} · população: ${f(s.population,0)}<br>Premissa de população: ${esc(s.populationBasis)}</p><h2>Memória e definição da população</h2>${populationMemory()}<div class="minimum-alert"><strong>Quantidade mínima de elevadores</strong><p>${esc(minimumMessage(s,r.minimum))}</p></div><div class="note">Demanda em 5 min: ${f(r.required)} pessoas (${f(r.rate*100,0)}%). Capacidade NBR: ${f(r.normative.capacity)}. Capacidade FAB: ${f(r.manufacturer.capacity)}.<br>Intervalo NBR: ${f(r.normative.interval)} s. Intervalo FAB: ${f(r.manufacturer.interval)} s. Máximo: ${r.groupSeparated?'ver critério por grupo':r.zoneSeparated?'ver critério por zona':r.limit===null?'não exigido para apartamentos':f(r.limit)+' s'}.<br>Capacidade: ${r.normative.capacityPass===null?'sem conclusão':r.normative.capacityPass?'atende':'não atende'}. Intervalo: ${r.normative.intervalPass===null?'sem exigência ou sem conclusão':r.normative.intervalPass?'estimativa atende':'não atende'}.</div><h2>Entradas por conjunto</h2><table><thead><tr><th>Grupo</th><th>Un.</th><th>Lotação</th><th>Paradas</th><th>Percurso (m)</th><th>Vel. (m/s)</th><th>Porta</th><th>Largura (mm)</th></tr></thead><tbody>${s.groups.map((g,i)=>`<tr><td>${esc(g.label||'Grupo '+(i+1))}</td><td>${g.count}</td><td>${g.capacity}</td><td>${g.stops}</td><td>${f(g.travel)}</td><td>${f(g.speed)}</td><td>${esc(DOORS[g.door].label)}</td><td>${g.width}</td></tr>`).join('')}</tbody></table><h2>Premissas do fabricante</h2>${s.groups.map((g,i)=>`<p><strong>Grupo ${i+1}:</strong> a = ${f(g.acceleration)} m/s²; j = ${f(g.jerk)} m/s³; abertura ${f(g.open)} s; fechamento ${f(g.close)} s; soma ${Number.isFinite(g.open)&&Number.isFinite(g.close)?f(g.open+g.close):'—'} s; pré-abertura ${g.preOpeningEnabled?f(g.preOpening):'desligada'} s; entrada/saída ${f(g.passenger)} s/pessoa; partida ${f(g.start)} s/ciclo.</p>`).join('')}<h2>Resultados por conjunto</h2>${detailTable()}<h2>Componentes do ciclo</h2>${memory()}${startsSection(s,r,true)}${r.groupSeparated?(s.operation.profile==='measured'?performanceSection(s,r,{print:true}):''):r.zoneSeparated?'':travelCurvesSection(s,r,{print:true})+performanceSection(s,r,{print:true})+(r.procurement?.offers?.length?'':energySection(s,r,{print:true}))}<h2>Premissas utilizadas</h2><p>Critério: Precisão integral de interpolação. Serviço comum: ${s.commonService?'declarado':'não declarado'}. Tráfego predominante de subida. Lotação útil completa. Adicional de 10% em T3 + T4. Os resultados não certificam toda a instalação.</p><ul>${r.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul><h2>Operação complementar</h2><p>Gráficos de atendimento, dados por bloco e premissas operacionais apresentados acima. Perfil real usa contagens informadas; não substitui o cálculo populacional nem constitui simulação normativa de despacho.</p>${auxiliaryResults(true)}<h2>Itens normativos utilizados</h2>${normExcerpts()}<h2>Referências</h2>${SOURCES.map(x=>`<p>${esc(x.title)} · ${esc(x.location)}</p>`).join('')}<p>Baseado nas edições fornecidas. Revisão pelo responsável técnico necessária para uso profissional. Sem verificação da vigência das normas nesta etapa.</p>`;$('#print-report').innerHTML=frameReport(body+procurementSummary(r.procurement||portal.procurement,{print:true})+annexPages(s,r),portal.reportProfile||portal.profile);}
document.addEventListener('input',e=>{if(e.target.dataset.basicPath){changeBasicInput(e.target,false);return;}if(e.target.dataset.carKey!==undefined){if(e.target.type==='number')changeFleetInput(e.target);return;}if(e.target.dataset.walkwayKey!==undefined){changeWalkwayInput(e.target);return;}if(e.target.dataset.dimensionalFilter){portal.dimensionalFilters={...portal.dimensionalFilters,[e.target.dataset.dimensionalFilter]:e.target.value};return;}if(e.target.dataset.offerPath){applyOfferInput(e.target);return;}if(e.target.dataset.recordScope){applyRecordInput(e.target);return;}if(e.target.matches('[data-path]'))applyInput(e.target);});
