 if(action==='export'||action==='export-comparison'){if(!portal.available)throw Error('Exportação autorizada requer conexão com a conta.');await verifyReportAccess();const data=await api('export-study',{method:'POST',body:JSON.stringify({projectId:portal.project.id})});if(action==='export-comparison'){exportComparison();return;}download(safeName(portal.fileLabel||state.draft.name)+'.json',JSON.stringify(data,null,2),'application/json');return;}
