 if(['open-dimensional-catalog','load-dimensional-catalog','clear-dimensional-filters','more-dimensional-catalog','apply-dimensional-product'].includes(action)){await dimensionalAction(action,data);return;}if(action==='refresh-workspace'){await refreshWorkspace();render();}
 else if(action==='save-project'){clearTimeout(portal.saveTimer);await saveProject(reportReady(dirty,result));await refreshWorkspace();render();toast(dirty?'Rascunho salvo. O relatório exige cálculo completo.':'Projeto calculado salvo.');}
