async function loadProcurement(){if(isBasic(state.draft)||portal.project.licenseLocked)return;if(!portal.project.id||!portal.available)return;const data=await api('projects/'+portal.project.id+'/offers');portal.procurement=data;portal.project.canManage=data.canManage;if(result)result.procurement=data;if(data.canManage)portal.access=(await api('projects/'+portal.project.id+'/access')).access;if(portal.project.role==='supplier'||!portal.project.role&&['supplier','supplier_manager','supplier_employee'].includes(portal.user.role)){portal.offerSupplier=data.ownSupplierId||portal.user.id;if(!portal.offerDraft)selectOfferSupplier(portal.offerSupplier);}if(state.view==='procurement')render();}
function selectOfferSupplier(id){if(portal.offerDirty&&id!==portal.offerSupplier){const select=$('#offer-supplier');if(select)select.value=portal.offerSupplier;toast('Salve a proposta ou descarte suas alterações antes de escolher outro fornecedor.');return;}portal.offerDirty=false;portal.offerSupplier=id;const existing=portal.procurement?.offers.find(o=>o.supplierId===id);portal.offerDraft=id?clone(existing?.data||newOffer(state.draft,{blank:true})):null;portal.offerRevision=existing?.revision||0;portal.catalogStatus={};portal.catalogConflict=null;render();}
let productTimer,productSequence=0;
function applyOfferInput(el){if(!portal.offerDraft)return;const path=el.dataset.offerPath,keys=path.split('.');let obj=portal.offerDraft;for(const key of keys.slice(0,-1))obj=obj[key];const key=keys.at(-1);obj[key]=el.type==='checkbox'?el.checked:el.tagName==='SELECT'&&['preOpeningEnabled'].includes(key)?el.value==='true':el.tagName==='SELECT'&&key==='trials'?Number(el.value):el.type==='number'?(el.value===''?null:Number(el.value)):el.value;if(keys[0]==='groups'){const product=portal.offerDraft.groups[Number(keys[1])].product;if(path.endsWith('.powerMode')&&el.value==='estimated'){const power=referencePower(portal.offerDraft.groups[Number(keys[1])]);product.motorPowerKw=power.mechanicalKw;product.movingKw=power.electricKw;}if(path.endsWith('.motorPowerKw')||path.endsWith('.movingKw'))product.powerMode='declared';}if(keys[0]==='groups'){const g=portal.offerDraft.groups[Number(keys[1])],d=g.product?.dimensions;if(d){if(path.endsWith('.survey.doorType'))d.existingDoorType=d.survey.doorType;if(keys.length===3&&key==='door')d.doorType=g.door;if(keys.length===3&&key==='width')d.doorWidth=g.width;if(path.endsWith('.dimensions.doorType'))g.door=d.doorType;if(path.endsWith('.dimensions.doorWidth'))g.width=d.doorWidth;if(path.includes('.dimensions.')&&['headroomMin','pitMin',...Object.keys(SHAFT_FIELDS)].includes(key))confirmManufacturerDimension(g,key);applyDimensionReference(g);for(const k of ['headroomMin','pitMin',...Object.keys(SHAFT_FIELDS)])if(k!==key){const input=$('#offer-groups-'+keys[1]+'-product-dimensions-'+k);if(input){input.value=d[k]??'';input.classList.toggle('required-empty',d[k]===null||d[k]===undefined);}}const reference=$('#offer-dimension-reference-'+keys[1]);if(reference)reference.innerHTML=dimensionReferenceHtml(g,{esc,f})+shaftReferenceHtml(g,{esc,f,choiceAttributes:`data-offer-path="groups.${keys[1]}.shaftRowId"`});}}portal.offerDirty=true;if($('#offer-readiness'))$('#offer-readiness').innerHTML=offerReadiness(portal.offerDraft,state.draft);if(keys[0]==='groups'){const i=Number(keys[1]),g=portal.offerDraft.groups[i],check=motionCheck(g),spec=evaluateOffer(state.draft,{company:'Prévia da proposta',data:portal.offerDraft}),required=spec.results?.starts.rows[i]?.requiredPerCar;for(const [k,yellow,red] of [['acceleration',check.accelerationYellow,check.accelerationRed],['jerk',check.jerkYellow,false],['startsLimit',g.startsLimit===0,required!==undefined&&g.startsLimit>0&&g.startsLimit<required]]){const input=$('#offer-groups-'+i+'-'+k);input?.classList?.toggle('motion-warning-yellow',yellow);input?.classList?.toggle('motion-warning-red',red);}const warning=$('#offer-warnings-'+i);if(warning)warning.textContent=[accelerationMessage(g),jerkMessage(g),g.startsLimit===0?'PPH do fabricante não informado.':required!==undefined&&g.startsLimit<required?'Não atendimento: PPH limite inferior às '+f(required)+' partidas/h necessárias por elevador.':''].filter(Boolean).join(' ');}const status=$('#offer-draft-status');if(status)status.textContent='Alterações da proposta não salvas. Salve e calcule a proposta para atualizar relatórios.';document.querySelectorAll('[data-action=print],[data-action=download-report],[data-action=download-pptx],[data-action=create-share]').forEach(b=>b.disabled=true);if(['preOpeningEnabled','doorAction','powerMode','source'].includes(key)||path.includes('destinationControl.')&&['enabled','method','system'].includes(key))render();if(['speed','capacity','model','cabinWidth','cabinDepth','cabinHeight','doorHeight','cabinType','machineRoom','fabrication','doorType','doorWidth','doorCount','doorArrangement'].includes(key)){clearTimeout(productTimer);const seq=++productSequence,index=Number(keys[1]);productTimer=setTimeout(()=>loadProduct(index,seq).catch(e=>toast(e.message)),600);}}
async function loadProduct(index,sequence){const group=portal.offerDraft?.groups[index];if(!group)return;if(!group.product?.model?.trim()||!(group.speed>0)||!(group.capacity>0))return;const d=group.product.dimensions||{},query=new URLSearchParams({supplierId:portal.offerSupplier,key:productKey(group),model:group.product.model,speed:String(group.speed),capacity:String(group.capacity),door:group.door,width:String(group.width)});for(const key of ['machineRoom','fabrication','cabinType','cabinWidth','cabinDepth','cabinHeight','doorWidth','doorHeight','doorCount','doorArrangement'])if(d[key]!==null&&d[key]!==undefined&&d[key]!=='')query.set(key,String(d[key]));const data=await api('projects/'+portal.project.id+'/catalog?'+query);if(sequence&&sequence!==productSequence)return;if(data.record){const applied=applyCatalogGroup(group,{...data.record,company:portal.access.find(a=>a.member_id===portal.offerSupplier)?.company||'Fornecedor'});portal.offerDraft.groups[index]=applied;portal.offerDirty=true;portal.catalogStatus[index]='Últimos dados preenchidos automaticamente'+(data.record.latestMatch?' para modelo, velocidade, lotação e porta; confira a variante dimensional':'')+'. Cadastro anterior por '+data.record.updatedEmail+'. Medições de campo não são reutilizadas; confira em loco neste projeto.';}else portal.catalogStatus[index]='Sem cadastro anterior para modelo, velocidade e capacidade. Última altura e poço seguem a tabela provisória quando houver correspondência; potências/correntes vazias usam estimativas identificadas.';render();}
async function saveProduct(index,confirm=false){const group=portal.offerDraft.groups[index],key=productKey(group),previous=await api('projects/'+portal.project.id+'/catalog?supplierId='+encodeURIComponent(portal.offerSupplier)+'&key='+encodeURIComponent(key));const revision=confirm?portal.catalogConflict.revision:previous.record?.revision||0;try{await api('projects/'+portal.project.id+'/catalog',{method:'PUT',body:JSON.stringify({supplierId:portal.offerSupplier,key,data:group,revision,confirmOverwrite:confirm})});portal.catalogConflict=null;portal.catalogStatus[index]='Cadastro mais recente salvo por '+portal.user.email;render();}catch(e){if(e.previous){portal.catalogConflict={...e.previous,index};render();}else throw e;}}
async function readInvoiceFile(){const file=$('#invoice-file')?.files?.[0];if(!file)throw Error('Selecione a conta de energia.');if(file.size>2000000||!['application/pdf','image/png','image/jpeg'].includes(file.type))throw Error('Use PDF, PNG ou JPEG de até 2 MB.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});return {file:data,name:file.name,mime:file.type};}
async function procurementAction(action,data){const path='projects/'+portal.project.id+'/';
 if(action==='refresh-procurement'){if(!portal.offerDirty)portal.offerDraft=null;await loadProcurement();render();}
 else if(action==='invite-project'){if(!portal.project.id)throw Error('Salve o projeto primeiro.');const date=$('#invite-expiry').value;const r=await api(path+'access',{method:'POST',body:JSON.stringify({company:$('#invite-company').value,name:$('#invite-name').value,email:$('#invite-email').value,kind:$('#invite-kind').value,expiresAt:date?new Date(date).toISOString():null})});portal.inviteUrl=r.url;await loadProcurement();render();}
 else if(action==='revoke-project-access'){await api(path+'access/'+data.id,{method:'DELETE'});await loadProcurement();}
 else if(action==='save-offer'){try{await api(path+'offers',{method:'PUT',body:JSON.stringify({supplierId:portal.offerSupplier,data:portal.offerDraft,revision:portal.offerRevision,baseRevision:portal.project.revision})});}catch(e){if(e.catalogConflict&&e.previous){portal.catalogConflict={...e.previous,index:e.previous.index};render();toast(e.message);return;}throw e;}portal.offerDirty=false;portal.offerDraft=null;await loadProcurement();if(portal.offerSupplier)selectOfferSupplier(portal.offerSupplier);toast('Proposta enviada. Pendências permanecem visíveis e serão consideradas na avaliação.');}
 else if(action==='discard-offer'){portal.offerDirty=false;selectOfferSupplier(portal.offerSupplier);}
 else if(action==='load-product')await loadProduct(Number(data.index));
 else if(action==='save-product')await saveProduct(Number(data.index));
 else if(action==='confirm-product')await saveProduct(portal.catalogConflict.index,true);
 else if(action==='cancel-product'){portal.catalogConflict=null;render();}
 else if(action==='load-audit'){portal.audit=(await api(path+'audit')).events;render();}
 else if(action==='analyze-invoice'){const file=await readInvoiceFile();const r=await api(path+'invoice-analysis',{method:'POST',body:JSON.stringify({...file,text:$('#invoice-text').value})});portal.invoiceDraft=r;portal.invoiceMessage='Leitura assistida: confira consumo e custos antes de salvar.';$('#invoice-kwh').value=r.consumptionKwh??'';$('#invoice-energy').value=r.energyCost??'';$('#invoice-total').value=r.totalCost??'';toast(portal.invoiceMessage);}
 else if(action==='save-invoice'){if(!$('#invoice-confirm').checked)throw Error('Confira os dados e marque a confirmação.');const file=await readInvoiceFile(),r=await api(path+'invoice',{method:'POST',body:JSON.stringify({...file,consumptionKwh:Number($('#invoice-kwh').value),energyCost:Number($('#invoice-energy').value),totalCost:Number($('#invoice-total').value),method:portal.invoiceDraft?.method||'manual'})});portal.invoiceDraft=r;portal.invoiceMessage='Conta e custos variáveis salvos. Para alterar a tarifa do estudo, o responsável deve aplicá-la e recalcular.';await loadProcurement();render();}
 else if(action==='apply-invoice-tariff'){const invoice=portal.procurement?.invoice?.[0];if(!invoice)throw Error('Salve a conta conferida primeiro.');state.draft.energy.tariff=invoice.tariff;markDirty();persist();render();toast('Tarifa variável aplicada. Calcule novamente o estudo completo.');}
 else if(action==='approve-share'){const r=await api('shares/'+data.id+'/approve',{method:'POST',body:'{}'});portal.shareUrl=r.url;portal.shares=(await api(path+'shares')).shares;render();toast('Compartilhamento aprovado; link registrado na auditoria.');}
 else return false;return true;
}


function servedFloorSelect(row,i){return `<div class="field"><label for="f-populationCalc-rows-${i}-servedFloorMark">Andar servido pela composição</label><select id="f-populationCalc-rows-${i}-servedFloorMark" data-path="populationCalc.rows.${i}.servedFloorMark" data-served-floor>${state.draft.floorTable.rows.map(r=>`<option value="${esc(r.mark)}" ${row.servedFloorMark===r.mark?'selected':''}>${esc(r.mark)}</option>`).join('')}</select><small>Nível e distância definidos na tabela de pavimentos. Ambientes do mesmo andar são somados.</small></div>`;}
function renameStudyReferences(previous,next){if(!next||next===previous)return;document.title=next+' · SilSec';for(const draft of Object.values(state.draft.modelDrafts||{}))if(draft.name===previous)draft.name=next;if(state.draft.projectDetails.name===previous)state.draft.projectDetails.name=next;if(state.draft.building===previous)state.draft.building=next;}
function changeBuildingInput(el){if(isReadOnly())return;try{if(el.dataset.buildingMark!==undefined)state.draft=setBuildingMark(state.draft,Number(el.dataset.buildingMark),el.value);else{const s=clone(state.draft),i=Number(el.dataset.buildingHeight??el.dataset.index);if(el.dataset.buildingHeight!==undefined){const value=Number(el.value);if(!(value>0&&value<=100))throw Error('Informe uma distância positiva de até 100 m.');s.floorTable.rows[i].height=value;}else{const id=el.dataset.buildingGroup,row=s.floorTable.rows[i],g=s.groups.find(g=>g.id===id);row.served[id]=el.checked;if(g?.cars)for(const car of g.cars)car.servedFloorIds=[...new Set(el.checked?[...car.servedFloorIds,row.id]:car.servedFloorIds.filter(x=>x!==row.id))];}s.floorTable.enabled=true;state.draft=synchronizeFloorTable(s);}if(state.draft.populationCalc.escalators.enabled)state.draft.populationCalc.escalators.capacityConfirmed=false;state.draft.entryVersion=8;state.draft=ensureFloorCompositions(state.draft);syncPhysicalInputs();markDirty();persist();render();}catch(e){toast(e.message);render();}}
function groupStudiesSection(r,print=false){return `<section class="group-studies"><h2>Estudo separado de cada grupo</h2>${r.groupStudies.map((c,i)=>{const x=c.results,m=x.iso||x.normative;return `<article class="card card-body"><h3>${esc(c.label)}</h3><p>${esc(c.basis)} Andares: ${c.floorMarks.map(esc).join(', ')||'conforme cadastro'}. População: ${f(c.population,0)}; Demanda: ${f(x.required)} pessoas/5 min.</p><p>Capacidade ${f(m.capacity)} pessoas/5 min · intervalo ${f(m.interval)} s. Capacidade ${m.capacityPass===null?'ver zonas':m.capacityPass?'atende':'não atende'}; intervalo ${m.intervalPass===null?'sem exigência ou ver zonas':m.intervalPass?'atende':'não atende'}.</p><p>${esc(minimumMessage(c.study,x.minimum))}</p>${x.iso?isoResultsTable(x)+isoMemory(x)+isoStartsSection(x):detailTable(x)+memory(x)+startsSection(c.study,x,print)}${(x.motionWarnings||[]).map(w=>`<p class="motion-summary ${w.level||w.severity||'yellow'}">${esc(w.message||w.text||w)}</p>`).join('')}${x.zoneSeparated?zonesSection(x,print):print?travelCurvesSection(c.study,x,{print:true,prefix:'logical-'+i})+performanceSection(c.study,x,{print:true,prefix:'logical-'+i})+energySection(c.study,x,{print:true,prefix:'logical-'+i}):''}</article>`;}).join('')}</section>`;}
function zonesSection(r,print=false){if(r?.groupSeparated)return groupStudiesSection(r,print);if(!r?.zoneSeparated)return '';return `<section class="zones-results"><h2>Atendimento separado por zona</h2><p>Grupos com destinos diferentes não compartilham automaticamente a população. Cada zona abaixo utiliza seus pavimentos, população e critérios próprios.</p>${r.zones.map((z,i)=>{const m=z.results.iso||z.results.normative;return `<article class="card card-body"><h3>${esc(z.label)} · ${z.study.groups.map(g=>esc(g.label)).join(', ')}</h3><p>Andares: ${z.floorMarks.map(esc).join(', ')}. População ${f(z.population,0)}; demanda ${f(z.results.required)} pessoas/5 min; capacidade ${f(m.capacity)}; intervalo ${f(m.interval)} s.</p><p>${esc(minimumMessage(z.study,z.results.minimum))}</p>${print?`${detailTable(z.results)}${z.results.iso?isoMemory(z.results):memory(z.results)}${z.results.iso?isoStartsSection(z.results):startsSection(z.study,z.results,true)}${travelCurvesSection(z.study,z.results,{print:true,prefix:'zone-'+i})}${performanceSection(z.study,z.results,{print:true,prefix:'zone-'+i})}${energySection(z.study,z.results,{print:true,prefix:'zone-'+i})}`:''}</article>`;}).join('')}</section>`;}

function registeredEscalatorFloors(){const pc=state.draft.populationCalc,table=state.draft.floorTable?.enabled?floorGeometry(state.draft):[];const values=new Map([[0,table.find(f=>f.level===0)?.mark||'0']]);for(const row of pc.rows){const f=table.find(f=>f.mark===row.servedFloorMark);values.set(f?.level??row.floor,row.servedFloorMark);}return [...values].map(([level,mark])=>({level,mark})).sort((a,b)=>a.level-b.level);}
function configureFloorEscalators(index,show=true){if(!hasSelectedEscalatorFloor(state.draft)){toast('Selecione os pavimentos atendidos por escadas na tabela do edifício.');return;}const pc=state.draft.populationCalc,row=pc.rows[index];if(!row)return;row.escalatorDiscount=true;if(pc.escalators.graphVersion===2){pc.escalators.enabled=true;state.escalatorFocus=index;if(show){markDirty();persist();render();}return;}const config=pc.escalators,floors=registeredEscalatorFloors(),available=new Set(floors.map(f=>f.level));if(config.graphVersion!==1){config.links=config.links.filter(l=>available.has(l.floor)&&l.floor!==0).map(l=>({...l,id:crypto.randomUUID(),from:l.floor+(l.floor>0?-1:1)}));config.links=config.links.filter(l=>available.has(l.from));}config.graphVersion=1;config.enabled=true;config.allowedFloors=floors.map(f=>f.level);config.capacityConfirmed=false;const target=row.floor,direction=Math.sign(target);for(let level=direction;direction&&Math.abs(level)<=Math.abs(target);level+=direction){if(!available.has(level)||!available.has(level-direction))continue;if(!config.links.some(l=>l.floor===level))config.links.push({...defaultEscalatorLink(level),id:crypto.randomUUID(),from:level-direction});}state.escalatorFocus=index;if(show){markDirty();persist();render();$('#escalator-title')?.scrollIntoView({block:'start',behavior:'smooth'});}}
function graphEscalatorForm(preview){const pc=state.draft.populationCalc,c=pc.escalators,p='populationCalc.escalators.',floors=registeredEscalatorFloors();c.allowedFloors=floors.map(f=>f.level);const options=Object.fromEntries(floors.map(f=>[f.level,f.mark]));return `<section class="transport-section"><h3 id="escalator-title">Escadas rolantes por pavimento cadastrado</h3>${button('upgrade-escalators','Configurar trechos e quantidades por sentido','small','refresh')}<p>${esc(isIso(state.draft)?ESCALATOR_EXCLUSION_HELP.replace('NBR 5665, item 5.1.6','documento ISO informado, item 4.3.3.4'):ESCALATOR_EXCLUSION_HELP)}</p><p>Somente andares com uma composição podem ser origem ou destino. O acesso 0 é a única exceção. Se faltar um andar intermediário, cadastre sua composição antes de confirmar a continuidade.</p>${checkField('Controlar atendimento por escadas rolantes',p+'enabled','Selecione os pavimentos na tabela de atendimento.',hasSelectedEscalatorFloor(state.draft)?'':'disabled')}${c.enabled?`<div class="fields">${select('Base de capacidade',p+'capacityBasis',{'provided-table':'Tabela enviada',manufacturer:'Dados documentados do fabricante'})}${field('Janela de transporte (min)',p+'periodMinutes')}${field('Demanda populacional na janela (%)',p+'demandPercent')}${field('Utilização da capacidade (%)',p+'utilizationPercent')}</div>${[...c.links].map((l,i)=>({l,i})).sort((a,b)=>b.l.floor-a.l.floor).map(({l,i})=>{const q=p+'links.'+i+'.';return `<details class="details-box" open><summary>Trecho ${floorCaption(l.from)} → ${floorCaption(l.floor)}</summary><div class="fields">${select('Andar de origem, em direção ao acesso',q+'from',options)}${select('Andar atendido pelo trecho',q+'floor',options)}${checkField('Trecho servido',q+'served')}${checkField('Escada para subir',q+'upPresent')}${checkField('Escada para descer',q+'downPresent')}${select('Largura subida (mm)',q+'widthUp',{600:'600',800:'800',1000:'1000'})}${select('Largura descida (mm)',q+'widthDown',{600:'600',800:'800',1000:'1000'})}${field('Velocidade subida (m/s)',q+'speedUp')}${field('Velocidade descida (m/s)',q+'speedDown')}${field('Inclinação (°)',q+'incline')}${field('Desnível (m)',q+'rise','number',state.draft.floorTable?.enabled?'Derivado das distâncias entre os pavimentos na tabela.':'Informe o desnível real do trecho.',state.draft.floorTable?.enabled?'readonly':'')}${c.capacityBasis==='manufacturer'?field('Capacidade subida (pessoas/h)',q+'capacityUpHourly')+field('Capacidade descida (pessoas/h)',q+'capacityDownHourly'):''}</div><div class="buttons">${button('remove-escalator-link','Remover trecho','small','trash',`data-index="${i}"`)}</div></details>`;}).join('')}<div class="buttons">${button('add-escalator-link','Adicionar trecho','small','plus')}</div><div id="escalator-results">${preview?escalatorResults(preview.escalators):'<p>Complete os trechos para verificar continuidade e capacidade. Até essa confirmação, a população é mantida nos elevadores.</p>'}</div>`:''}</section>`;}

function populationFloorSelection(){const marks=new Set(state.draft.populationCalc.rows.map(r=>r.servedFloorMark));return marks.has(state.populationFloorMark)?state.populationFloorMark:state.draft.populationCalc.rows[state.populationRow||0]?.servedFloorMark;}
