function syncPhysicalInputs(){if(state.draft.populationCalc.escalators.graphVersion===2)state.draft=remodelEscalators(state.draft);}
function upgradeEscalatorLayout(){if(!state.draft.floorTable.enabled)state.draft.floorTable.enabled=true;state.draft.entryVersion=8;state.draft=ensureFloorCompositions(state.draft);state.draft=remodelEscalators(state.draft,{all:true});state.draft.populationCalc.escalators.enabled=true;}
async function dimensionalAction(action,data){if(!portal.available)throw Error('Conecte sua conta para consultar o catálogo.');if(action==='apply-dimensional-product'){if(isReadOnly()&&!portal.offerDraft)throw Error('Este projeto está em consulta.');const record=portal.dimensionalCatalog?.records.find(r=>r.id===data.id),index=Number($('#catalog-target-group').value);if(portal.project.role==='supplier'||['supplier','supplier_manager','supplier_employee'].includes(portal.user?.role)){if(!record||!portal.offerDraft)throw Error('Abra sua proposta antes de aplicar o catálogo.');portal.offerDraft.groups[index]=applyCatalogGroup(portal.offerDraft.groups[index],record);portal.offerDirty=true;state.view='procurement';render();return;}if(!record||!state.draft.groups[index])throw Error('Selecione produto e grupo válidos.');state.draft.groups[index]=applyCatalogGroup(state.draft.groups[index],record);state.group=index;state.parameterTab='traffic';state.view='parameters';markDirty();persist();render();toast('Produto e tempos preenchidos a partir do catálogo. Confira e calcule novamente.');return;}if(action==='clear-dimensional-filters')portal.dimensionalFilters={};const offset=action==='more-dimensional-catalog'?portal.dimensionalCatalog?.nextOffset||0:0;const query=new URLSearchParams({...portal.dimensionalFilters,offset:String(offset),...(portal.project.id?{projectId:portal.project.id}:{})});portal.dimensionalCatalog=await api('dimensional-catalog?'+query);portal.dimensionalMessage=portal.dimensionalCatalog.records.length+' configuração(ões) encontradas nesta página.';state.view='dimensions';render();}

