function changeTransportSelection(el){if(isReadOnly()||!['rolling','escalators','walkways'].includes(el.dataset.transportKind))return;const c=transportOptions(state.draft),value=el.value==='yes'?true:el.value==='no'?false:null;Object.assign(c,{rolling:value,escalators:value,walkways:value});state.draft.transportEquipment=c;state.draft.populationCalc.escalators.enabled=value===true;if(value===true){normalizeFloorTable(state.draft);initializeEscalatorSelection(state.draft);state.draft.floorTable.enabled=true;state.draft=remodelEscalators(state.draft,{all:true});state.parameterTab=escalatorTabAvailable(state.draft)?'escalators':'traffic';}else state.parameterTab='traffic';markDirty();persist();render();}
function changeEscalatorFloor(el){if(isReadOnly()||transportOptions(state.draft).rolling!==true)return;try{state.draft.transportEquipment={...transportOptions(state.draft),rolling:true,escalators:true,walkways:true};state.draft=selectEscalatorFloor(state.draft,Number(el.dataset.buildingEscalator),!!el.checked);state.draft=remodelEscalators(state.draft,{all:true});state.draft.populationCalc.escalators.enabled=hasSelectedEscalatorFloor(state.draft);markDirty();persist();render();}catch(error){toast(error.message);render();}}

function changeWalkwayInput(el){if(isReadOnly())return;const c=transportOptions(state.draft),row=c.walkwaysRows?.[Number(el.dataset.walkwayIndex)],key=el.dataset.walkwayKey;if(c.walkways!==true||!row||!['label','length','speed','width','count','capacity','document','population'].includes(key))return;row[key]=['label','document'].includes(key)?el.value:el.value===''?null:Number(el.value);state.draft.transportEquipment=c;markDirty();persist();updateDerived();}
function focusPending(data){const target=pendingTarget(state.draft,Number(data.section),Number(data.item));if(!target)return;state.view=target.view||'parameters';if(target.group!==undefined)state.group=target.group;if(target.parameterTab)state.parameterTab=target.parameterTab;if(target.row!==undefined){state.populationRow=target.row;state.populationFloorMark=state.draft.populationCalc.rows[target.row]?.servedFloorMark;}if(target.analysisTab)state.analysisTab=target.analysisTab;persist();render();let el=target.id?$('#'+target.id):document.querySelector('[data-path="'+target.path+'"]');if(!el&&target.path)el=$('#f-'+target.path.replaceAll('.','-'));if(!el){toast('Campo pendente indisponível nesta versão.');return;}for(let node=el.parentElement;node;node=node.parentElement)if(node.tagName==='DETAILS')node.open=true;el.scrollIntoView?.({block:'center',behavior:'smooth'});el.focus?.();}

function moduleSwitcher(){return `<div class="module-switcher"><button class="btn small" data-action="module-basic">Novo Básico</button><button class="btn small" data-action="module-advanced">Novo Avançado</button></div>`;}
function moduleShell(content){return `<div class="module-layout"><header class="module-header"><div class="silsec-module-brand"><img class="silsec-logo" src="/silsec-brand/opcao-1.png" alt="SilSec" width="1942" height="809"><span>Estudo de tráfego</span></div>${!sharedReadOnly?moduleSwitcher():''}<nav>${!sharedReadOnly?['projects','clients','profile','subscription',...(portal.user?.role==='admin'?['team']:[])].map(v=>`<button class="btn small" data-action="navigate" data-view="${v}">${esc(views[v])}</button>`).join(''):''}</nav></header><main id="main">${sharedReadOnly?'':licenseBanner(effectiveLicense()||(!cloudRuntime?resolveLicenses({role:'admin'}):null),studyModule(state.draft))}${content}<footer class="page-foot">Protótipo privado ${ENGINE_VERSION} · cobrança desativada · <a href="/descricao-do-programa.md" target="_blank" rel="noreferrer">Descrição do programa</a></footer></main><div id="print-report" class="print-report"></div></div>`;}
function changeBasicInput(el,redraw=true){if(isReadOnly()||!isBasic(state.draft))return;const path=el.dataset.basicPath,keys=path?.split('.');if(!keys||!(/^(name|client|building|address|date|use|populationDefinition)$/.test(path)||/^groups\.\d+\.(label|use|population|count|capacity|stops|travel|speed|width|door)$/.test(path)||/^(customer\.(address|phone|email|contact)|projectDetails\.(contact|phone)|annex\.(owner|author|builder|engineer|installer|notes))$/.test(path)))return;let target=state.draft;for(const k of keys.slice(0,-1))target=target?.[k];if(!target)return;const previous=target[keys.at(-1)];if(path==='client')state.draft.customer.companyName=el.value;if(['name','building'].includes(path)&&(!state.draft.projectDetails.name||state.draft.projectDetails.name===previous))state.draft.projectDetails.name=el.value;if(path==='address'&&(!state.draft.projectDetails.address||state.draft.projectDetails.address===previous))state.draft.projectDetails.address=el.value;target[keys.at(-1)]=el.type==='number'?(el.value===''?null:Number(el.value)):el.value;markDirty();persist();if(redraw)render();else{document.querySelectorAll('[data-action="print"],[data-action="download-report"]').forEach(el=>el.disabled=true);document.querySelectorAll('[data-basic-result] td').forEach(el=>el.textContent='Calcule para atualizar');}}
function calculateBasicUi(){if(isReadOnly())return false;try{const computed=recalculatePopulationAndStudies(state.draft);state.draft=computed.study;result=computed.results;dirty=false;errors=[];state.view='basic';persist();render();scheduleCloudSave(true);toast('Cálculo normativo concluído por grupo.');return true;}catch(e){dirty=true;result=null;errors=e.message.split('\n');render();toast('Confira os campos indicados antes de calcular.');return false;}}
async function loadLicenses(){if(!portal.available)return;portal.licenseData=await api('licenses');portal.entitlements=portal.licenseData.entitlements;render();}
async function startModule(module,clientId=null){if(portal.available&&!staff(portal.user))throw Error('Seu acesso de convidado permite colaborar nos projetos autorizados. Solicite um perfil de equipe para criar estudos próprios.');if(!moduleAllowed(module)){state.view='subscription';await loadLicenses();render();toast('Solicite uma assinatura ou concessão para abrir este módulo.');return;}if(portal.offerDirty)throw Error('Salve ou descarte a proposta antes de criar outro estudo.');clearTimeout(portal.saveTimer);await portal.saveChain.catch(()=>{});if(portal.available&&!isReadOnly()&&(portal.project.id||dirty))await saveProject(reportReady(dirty,result));const client=portal.clients.find(c=>c.id===clientId);detachProject();state.draft=module==='basic'?newBasic():normalizeStudy(newStudy());state.view=module==='basic'?'basic':'study';state.group=0;state.scenarios=[];portal.project={id:null,revision:null,canEdit:true,canManage:staff(portal.user),ownerId:portal.user?.id};portal.procurement=null;portal.reportProfile=portal.profile;if(client){state.clientRecordId=client.id;state.draft.client=client.companyName;state.draft.customer=Object.fromEntries(Object.keys(emptyCustomer()).map(k=>[k,client[k]||'']));}dirty=true;result=null;errors=[];persist();render();if(module==='advanced')toast(accessMessage(effectiveLicense()));}
async function moduleAction(action,data){if(action==='module-basic'||action==='module-advanced'){await startModule(action.slice(7));return;}if(action==='license-open'){state.view='subscription';render();await loadLicenses();return;}if(!portal.available)throw Error('Entre na conta privada para administrar as licenças.');const val=id=>$('#'+id)?.value||'',post=(path,body)=>api('licenses/'+path,{method:'POST',body:JSON.stringify(body)});let response;
 if(action==='license-purchase'){response=await post('purchase',{module:val('license-purchase-module'),period:val('license-period'),cpf:val('license-cpf')});toast(response.message);}
 else if(action==='license-redeem'){await post('redeem',{key:val('license-key')});toast('Chave ativada.');}
 else if(action==='license-grant'||action==='license-create-key'){const raw=val('license-end'),endsAt=raw?new Date(raw).toISOString():null;response=await post(action==='license-grant'?'grant':'key',{memberId:val('license-member'),module:val('license-grant-module'),permanent:!!$('#license-permanent')?.checked,endsAt});if(response.key)portal.generatedKey=response;toast(action==='license-grant'?'Concessão registrada.':'Chave gerada; copie antes de sair.');}
 else if(action==='license-revoke'){await api('licenses/grants/'+encodeURIComponent(data.id),{method:'DELETE'});toast('Concessão revogada.');}
 else if(action.includes('purchase')&&data.id){await post('purchase/'+encodeURIComponent(data.id),{decision:action==='license-approve-purchase'?'activate-demo':'reject'});toast('Solicitação revisada. Cobrança desativada.');}
 else if(action==='license-education'){const file=$('#education-file')?.files?.[0];if(!file||file.size>1800000||!['application/pdf','image/png','image/jpeg'].includes(file.type))throw Error('Envie PDF, PNG ou JPEG de até 1,8 MB.');const document=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});await post('education',{institution:val('education-institution'),issuedDate:val('education-date'),fileName:file.name,document});toast('Comprovante enviado. Aguarde análise da matrícula.');}
 else if(action.includes('education')&&data.id){await post('education/'+encodeURIComponent(data.id),{decision:action==='license-approve-education'?'approve':'reject'});toast('Comprovante revisado.');}
 await loadLicenses();if(portal.generatedKey){const box=document.createElement('section');box.className='card';box.innerHTML=`<h2>Chave temporária gerada</h2><p>Válida até ${esc(new Date(portal.generatedKey.endsAt).toLocaleString('pt-BR'))}. Exibida somente nesta sessão.</p><input aria-label="Chave temporária" readonly value="${esc(portal.generatedKey.key)}">`;$('#main')?.prepend?.(box);}
}

if(cloudRuntime&&window.setInterval)window.setInterval(()=>{if(!portal.available||sharedReadOnly||portal.project.licenseLocked||moduleAllowed(studyModule(state.draft)))return;clearTimeout(portal.saveTimer);if(portal.project.id)openProject(portal.project.id).catch(e=>toast(e.message));else{state.view='subscription';render();}},30000);

function updateIndividualFields(){
 let calculated;try{calculated=dirty&&state.view==='parameters'&&state.draft.groups.some(g=>fleetCars(state.draft,g).some(c=>c.startsLimit>0))?recalculatePopulationAndStudies(state.draft).results:dirty?null:result;}catch{}
 for(const [i,g] of state.draft.groups.entries()){
  const warnings=heightWarnings(g.siteDimensions);for(const key of ['cabinHeight','doorHeight']){const el=$('#f-groups-'+i+'-siteDimensions-'+key);el?.classList.toggle('motion-warning-red',warnings.some(w=>w.key===key));}const height=$('#height-warning-'+i);if(height)height.innerHTML=warnings.map(w=>'<p class="score-red">'+esc(w.message)+'</p>').join('');const area=$('#cabin-area-'+i);if(area)area.innerHTML=cabinAreaHtml(state.draft,g,{esc,f});const bad=groupCabinChecks(state.draft,g).some(c=>c.red);for(const key of ['cabinWidth','cabinDepth']){const el=$('#f-groups-'+i+'-siteDimensions-'+key);if(el){el.classList.toggle('motion-warning-red',bad);el.setAttribute('aria-invalid',String(bad));}}
  for(const [j,raw] of fleetCars(state.draft,g).entries()){
   const c=carTiming(state.draft,g,raw),prefix='#car-'+i+'-'+j+'-',warnings=$(prefix+'warnings');if(warnings)warnings.innerHTML=carWarnings(state.draft,g,raw,{f}).map(w=>`<p class="population-warning">${esc(w)}</p>`).join('');
   const accelRef=$(prefix+'norm-acceleration');if(accelRef)accelRef.textContent=f(accelerationTime(c.speed,'precision'))+' s';const ref=$(prefix+'norm-door');if(ref)ref.textContent=f(doorReference(state.draft,c))+' s';for(const key of ['capacity','speed','width','personMassKg','open','close','acceleration','jerk','transferPerStop','start','startsLimit','preOpening']){const el=$(prefix+key);if(el)el.classList.toggle('required-empty',!Number.isFinite(c[key]));}const total=$(prefix+'door-total');if(total)total.textContent=f(doorTotal(c))+' / '+f(doorReference(state.draft,c))+' s';
   const transfer=$(prefix+'transferPerStop');if(transfer&&raw.transferMode!=='per-stop'&&document.activeElement!==transfer)transfer.value=Number.isFinite(c.transferPerStop)?String(c.transferPerStop):'';
   for(const key of ['open','close','acceleration','jerk','startsLimit']){const el=$(prefix+key);if(!el)continue;const red=['open','close'].includes(key)&&doorExceeded(state.draft,c)||key==='acceleration'&&c.acceleration>1.6;const yellow=key==='acceleration'&&c.acceleration>1&&c.acceleration<=1.6||key==='jerk'&&c.jerk>(c.speed>2.5?1.6:1.2)||key==='startsLimit'&&c.startsLimit===0;el.classList.toggle('motion-warning-red',red);el.classList.toggle('motion-warning-yellow',yellow);el.setAttribute('aria-invalid',String(red));}
   const context=calculated?.groupStudies?.find(x=>x.id===g.id),r=context?.results||calculated,s=r?.calculationStudy||context?.study||r?.calculationStudy;
   const k=s?.groups?.findIndex(x=>(x.logicalGroupId||x.id)===g.id&&(!x.carNumbers||x.carNumbers.includes(j+1))),pph=k>=0?r.starts?.rows[k]?.requiredPerCar:null;
   if(Number.isFinite(pph)&&c.startsLimit>0&&c.startsLimit<pph){$(prefix+'startsLimit')?.classList.add('motion-warning-red');$(prefix+'startsLimit')?.setAttribute('aria-invalid','true');if(warnings)warnings.innerHTML+=`<p class="errors">Não atendimento: limite ${f(c.startsLimit)} PPH inferior a ${f(pph)} partidas/h necessárias.</p>`;}
  }
 }
}

function fiscalInput(prefix){return Object.fromEntries(['cnpj','name','tradeName','address','city','state','postalCode','taxRegistration','phone','contact','email'].map(k=>[k,$('#'+prefix+'-'+k)?.value||'']));}
async function silsecFile(selector){const file=$(selector)?.files?.[0];if(!file)throw Error('Selecione um documento.');if(file.size>2000000||!['application/pdf','text/plain','image/png','image/jpeg'].includes(file.type))throw Error('Use PDF, TXT, PNG ou JPG de até 2 MB.');const value=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});return {file:value,name:file.name,mime:file.type};}
async function silsecAction(action,data){
 const path='projects/'+portal.project.id+'/silsec/';
 if(['silsec-lookup-cnpj','silsec-submit-registration'].includes(action)){if(!portal.registrationToken)throw Error('Abra um convite válido.');if(action==='silsec-lookup-cnpj'){const r=await api('supplier-registration/'+portal.registrationToken+'?cnpj='+encodeURIComponent($('#registration-cnpj').value));portal.registrationData=r;$('#app').innerHTML=registrationPage(r);}else{const r=await api('supplier-registration/'+portal.registrationToken,{method:'POST',body:JSON.stringify(fiscalInput('registration'))});$('#registration-status').textContent=r.message;}return;}
 if(sharedReadOnly||portal.project.licenseLocked)throw Error('Acesso somente de consulta.');
 if(action==='silsec-close-dialog'){document.querySelectorAll('.silsec-dialog').forEach(x=>x.remove());return;}
 if(action==='silsec-copy-dimensions'){if(isReadOnly())throw Error('Sem edição do levantamento.');document.body.insertAdjacentHTML('beforeend',dimensionalCopyDialog(state.draft,Number(data.group),esc));return;}
 if(action==='silsec-confirm-dim-copy'){if(isReadOnly())throw Error('Sem edição do levantamento.');const targets=[...document.querySelectorAll('[data-dimension-target]:checked')].map(x=>Number(x.dataset.dimensionTarget));state.draft=copySiteDimensions(state.draft,Number(data.source),targets);$('#dim-copy-dialog')?.remove();markDirty();persist();render();return;}
 if(action==='silsec-dimension-catalog'){state.group=Number(data.group);await dimensionalAction('load-dimensional-catalog',{});if($('#catalog-target-group'))$('#catalog-target-group').value=String(state.group);return;}
 if(action==='silsec-select-organization'){portal.organizationData=await api('organization?organizationId='+encodeURIComponent(data.id));render();return;}
 if(action==='silsec-load-organization'){portal.organizationData=await api('organization');render();return;}
 if(action==='silsec-create-organization'){await api('organization',{method:'POST',body:JSON.stringify({...fiscalInput('org'),kind:$('#org-kind').value})});toast('Empresa e gestor cadastrados. Conceda os módulos e os acessos de projeto necessários.');return;}
 if(action==='silsec-save-org-member'){const permissions=Object.fromEntries([...document.querySelectorAll('[data-org-permission]')].map(el=>[el.dataset.orgPermission,el.checked]));await api('organization/member?organizationId='+encodeURIComponent(portal.organizationData?.organization?.id||''),{method:'PUT',body:JSON.stringify({email:$('#org-member-email').value,name:$('#org-member-name').value,permissions,projectId:portal.project.id})});portal.organizationData=await api('organization');render();toast('Acessos do funcionário atualizados para este projeto.');return;}
 if(!portal.project.id)throw Error('Salve o projeto antes desta operação.');
 if(action==='silsec-invite'){const r=await api(path+'invites',{method:'POST',body:JSON.stringify({email:$('#silsec-invite-email').value,days:Number($('#silsec-invite-days').value)})});portal.silsecInviteUrl=r.url;render();return;}
 if(action==='silsec-load-invites'){portal.silsecInvites=await api(path+'invites');render();return;}
 if(action==='silsec-approve-registration'){await api(path+'approve-registration',{method:'POST',body:JSON.stringify({id:data.id})});portal.silsecInvites=await api(path+'invites');await loadProcurement();render();return;}
 if(action==='silsec-save-commercial'){const read=id=>$('#sc-'+id)?.value??'',number=id=>read(id)===''?null:Number(read(id));await api(path+'commercial',{method:'PUT',body:JSON.stringify({supplierId:data.supplier,revision:Number(data.revision),data:{paymentTerms:read('payment'),delivery:read('delivery'),warranty:read('warranty'),exclusions:read('exclusions'),scope:read('scope'),legalNotes:read('legal'),targetPrice:number('target-price'),targetDiscountPercent:number('target-percent'),closedPrice:number('closed-price'),closedAt:read('closed-date'),status:read('status')}})});await loadProcurement();render();return;}
 if(action==='silsec-upload-doc'){const file=await silsecFile('#silsec-doc-file');await api(path+'documents',{method:'POST',body:JSON.stringify({...file,supplierId:data.supplier,category:$('#silsec-doc-category').value})});await loadProcurement();render();toast('Documento anexado. Se for comprovação de dados, selecione-o no campo Origem dos valores do produto.');return;}
 if(action==='silsec-energy-evidence'){if(isReadOnly())throw Error('Sem edição dos parâmetros do estudo.');document.body.insertAdjacentHTML('beforeend',`<dialog open class="silsec-dialog"><h2>Comprovação dos dados energéticos</h2><input type="file" id="energy-evidence-file" accept="application/pdf,text/plain,image/png,image/jpeg"><button class="btn" data-action="silsec-save-energy-evidence" data-technology="${esc(data.technology)}">Anexar</button><button class="btn" data-action="silsec-close-dialog">Cancelar</button></dialog>`);return;}
 if(action==='silsec-save-energy-evidence'){if(isReadOnly())throw Error('Sem edição dos parâmetros.');const file=await silsecFile('#energy-evidence-file'),r=await api(path+'documents',{method:'POST',body:JSON.stringify({...file,category:'evidence'})});state.draft.energy.technologies[data.technology].documentId=r.id;state.draft.energy.technologies[data.technology].reference=file.name;document.querySelectorAll('.silsec-dialog').forEach(x=>x.remove());markDirty();persist();render();return;}
 if(action==='silsec-analyze-contract'){toast('Analisando documento; aguarde a conclusão.');await api(path+'analyze-contract',{method:'POST',body:JSON.stringify({supplierId:data.supplier,documentId:data.document,consent:!!$('#silsec-ai-consent')?.checked})});await loadProcurement();render();return;}
 if(action==='silsec-review-analysis'){await api(path+'review-analysis',{method:'POST',body:JSON.stringify({supplierId:data.supplier})});await loadProcurement();render();return;}
 if(action==='silsec-negotiation-text'){const supplier=$('#silsec-supplier')?.value||portal.commercialSupplier||portal.offerSupplier||portal.procurement?.commercial?.[0]?.supplierId,o=portal.procurement?.offers.find(x=>x.supplierId===supplier),price=$('#sc-target-price')?.value,discount=$('#sc-target-percent')?.value,text='Prezados, '+(o?.company||'fornecedor')+'. Sobre a proposta para '+state.draft.name+', solicitamos avaliar '+(price?'o valor target de R$ '+Number(price).toLocaleString('pt-BR',{minimumFractionDigits:2}):'uma revisão comercial')+(discount?' (desconto de referência: '+discount+'%)':'')+', mantendo o escopo e as condições técnicas. Favor confirmar valores, pagamentos, prazos e exclusões.';document.body.insertAdjacentHTML('beforeend',`<dialog open class="silsec-dialog"><h2>Texto para conferir e encaminhar</h2><textarea rows="8">${esc(text)}</textarea><p>Confira se valor target e percentual são consistentes. Nenhuma mensagem foi enviada.</p><button class="btn" data-action="silsec-close-dialog">Fechar</button></dialog>`);return;}
}
